const TEST_BANK_DWEC = [

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 1 — Arquitecturas y lenguajes del entorno cliente
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dwec_u1_q1", unit:1, question:"¿En qué entorno se ejecuta JavaScript del lado cliente?", options:["En el servidor web","En el navegador web del usuario","En la base de datos","En un contenedor Docker"], correct:1, explanation:"JS client-side corre en el navegador, sin necesidad de servidor.", noShuffle:false },
  { concept_id:"dwec_u1_q2", unit:1, question:"¿Cuál de las siguientes NO es una forma válida de incluir JavaScript en HTML?", options:["<script src=\"app.js\"></script>","<script>alert('ok')</script>","<link rel=\"script\" href=\"app.js\">","onclick=\"fn()\" en un elemento"], correct:2, explanation:"La etiqueta <link> es para CSS. Para JS externo se usa <script src>.", noShuffle:false },
  { concept_id:"dwec_u1_q3", unit:1, question:"¿Qué significa que JavaScript sea un lenguaje 'interpretado'?", options:["Necesita compilarse antes de ejecutarse","El código fuente es ejecutado directamente por el motor del navegador","Solo puede ejecutarse en servidores Linux","Su código es binario"], correct:1, explanation:"Los lenguajes interpretados se ejecutan directamente por un intérprete (V8, SpiderMonkey) sin compilación previa.", noShuffle:false },
  { concept_id:"dwec_u1_q4", unit:1, question:"¿Para qué sirve el atributo 'defer' en <script>?", options:["Ejecuta el script antes del HTML","Deshabilita el script en móviles","El script se ejecuta después de parsear el HTML completo","Carga el script desde CDN"], correct:2, explanation:"defer descarga el script en paralelo pero lo ejecuta cuando el DOM está completamente parseado.", noShuffle:false },
  { concept_id:"dwec_u1_q5", unit:1, question:"¿Qué lenguaje define la estructura de una página web?", options:["CSS","JavaScript","HTML","PHP"], correct:2, explanation:"HTML define estructura, CSS estilos, JS comportamiento.", noShuffle:false },
  { concept_id:"dwec_u1_q6", unit:1, question:"¿Qué rol cumple el navegador en el modelo cliente-servidor?", options:["Servidor: procesa peticiones","Cliente: solicita recursos y los renderiza","Proxy entre dos servidores","Base de datos"], correct:1, explanation:"El navegador es el cliente: hace peticiones HTTP y renderiza la respuesta.", noShuffle:false },
  { concept_id:"dwec_u1_q7", unit:1, question:"¿Qué herramienta del navegador permite depurar JavaScript?", options:["El editor de texto del navegador","Las DevTools (F12)","El gestor de descargas","La barra de favoritos"], correct:1, explanation:"Las DevTools (F12) incluyen consola, depurador, inspector de red y DOM.", noShuffle:false },
  { concept_id:"dwec_u1_q8", unit:1, question:"¿Qué atributo de <script> permite la carga en paralelo SIN diferir la ejecución?", options:["defer","async","module","type=\"text/javascript\""], correct:1, explanation:"async descarga el script en paralelo y lo ejecuta en cuanto está disponible, sin esperar al DOM.", noShuffle:false },
  { concept_id:"dwec_u1_q9", unit:1, question:"¿Qué versión de ECMAScript introdujo let, const, arrow functions y clases?", options:["ES3","ES5","ES6 (ES2015)","ES2020"], correct:2, explanation:"ES6/ES2015 fue la mayor actualización de JavaScript, añadiendo let/const, arrow functions, clases, modules, Promises, etc.", noShuffle:false },
  { concept_id:"dwec_u1_q10", unit:1, question:"¿Cuál es el motor de JavaScript usado por Google Chrome y Node.js?", options:["SpiderMonkey","JavaScriptCore","V8","Chakra"], correct:2, explanation:"V8 es el motor de Google. SpiderMonkey es de Firefox, JavaScriptCore de Safari, Chakra de Edge antiguo.", noShuffle:false },
  { concept_id:"dwec_u1_q11", unit:1, question:"¿Cuál es la diferencia entre JavaScript y Java?", options:["Son el mismo lenguaje con distinto nombre","JavaScript es para web cliente; Java es un lenguaje compilado orientado a objetos completamente independiente","JavaScript solo corre en Windows; Java en todos los SO","JavaScript es más lento que Java siempre"], correct:1, explanation:"A pesar del nombre, son lenguajes completamente distintos. JS fue creado por Netscape; Java por Sun Microsystems.", noShuffle:false },
  { concept_id:"dwec_u1_q12", unit:1, question:"¿Qué es TypeScript en relación con JavaScript?", options:["Un framework de JavaScript para UI","Un superset de JavaScript que añade tipado estático y se transpila a JS","Un lenguaje completamente diferente","Un motor alternativo a V8"], correct:1, explanation:"TypeScript (Microsoft) añade tipos estáticos a JS. El compilador tsc lo convierte en JS estándar.", noShuffle:false },
  { concept_id:"dwec_u1_q13", unit:1, question:"¿Qué es el 'renderizado' en el contexto de los navegadores?", options:["El proceso de descargar archivos JS","El proceso de convertir el código HTML/CSS/JS en una página visual que el usuario ve","La compilación del código JavaScript","El envío de datos al servidor"], correct:1, explanation:"El motor de renderizado (Blink, Gecko, WebKit) procesa HTML/CSS y los convierte en la interfaz visual.", noShuffle:false },
  { concept_id:"dwec_u1_q14", unit:1, question:"¿Cuál de estos es un lenguaje de script que se ejecuta en el servidor?", options:["JavaScript","TypeScript","PHP","CoffeeScript"], correct:2, explanation:"PHP es un lenguaje de servidor. JS también puede ejecutarse en servidor con Node.js, pero en su forma nativa es de cliente.", noShuffle:false },
  { concept_id:"dwec_u1_q15", unit:1, question:"¿Qué es la consola del navegador (console)?", options:["Una terminal para ejecutar comandos del sistema operativo","Una herramienta de las DevTools para depurar JS, ver logs y errores","Un editor de código integrado en el navegador","Una pestaña para gestionar cookies"], correct:1, explanation:"console.log(), console.error(), console.warn()... son métodos del objeto console para depurar y registrar información.", noShuffle:false },
  { concept_id:"dwec_u1_q16", unit:1, question:"¿Qué estándar rige el lenguaje JavaScript?", options:["W3C Standard","ISO 9001","ECMAScript (ECMA-262)","HTML Living Standard"], correct:2, explanation:"JavaScript sigue el estándar ECMAScript definido por ECMA International. TC39 es el comité técnico que lo evoluciona.", noShuffle:false },
  { concept_id:"dwec_u1_q17", unit:1, question:"¿Qué tecnología permite escribir código JavaScript que se ejecuta en el servidor?", options:["Django","Node.js","Laravel","Apache"], correct:1, explanation:"Node.js usa el motor V8 de Chrome para ejecutar JavaScript fuera del navegador, permitiendo desarrollo backend con JS.", noShuffle:false },
  { concept_id:"dwec_u1_q18", unit:1, question:"¿Cuál de estas afirmaciones sobre JavaScript es FALSA?", options:["Es un lenguaje de tipado dinámico","Es un lenguaje orientado a objetos basado en prototipos","JavaScript y Java tienen la misma sintaxis","Puede manipular el DOM del navegador"], correct:2, explanation:"JavaScript y Java tienen sintaxis muy diferentes. Solo comparten el nombre por razones de marketing histórico.", noShuffle:false },
  { concept_id:"dwec_u1_q19", unit:1, question:"¿Cuál es la forma correcta de declarar una variable constante en ES6+?", options:["var PI = 3.14","let PI = 3.14","const PI = 3.14","constant PI = 3.14"], correct:2, explanation:"const declara una constante: su referencia no puede reasignarse. Es la opción preferida para valores que no cambian.", noShuffle:false },
  { concept_id:"dwec_u1_q20", unit:1, question:"¿Qué es el 'sandbox' del navegador en relación con JavaScript?", options:["Un entorno de desarrollo local sin internet","Un entorno aislado que limita lo que JS puede hacer por seguridad (ej: no acceder al sistema de archivos)","Una versión de prueba del navegador","Un tipo especial de iframe"], correct:1, explanation:"El sandbox impide que JS malicioso dañe el sistema del usuario: sin acceso al disco, sin control de otros programas.", noShuffle:false },
  { concept_id:"dwec_u1_q21", unit:1, question:"¿Qué hace el método console.log() en JavaScript?", options:["Registra mensajes en el servidor","Muestra información en la consola del navegador para depuración","Envía datos a la base de datos","Genera un alert en pantalla"], correct:1, explanation:"console.log() es la herramienta básica de depuración. No afecta al usuario final si las DevTools están cerradas.", noShuffle:false },
  { concept_id:"dwec_u1_q22", unit:1, question:"¿Cuál es la extensión habitual de los archivos JavaScript?", options:[".java",".js",".jsx",".script"], correct:1, explanation:"Los archivos JavaScript usan la extensión .js. Los archivos React JSX usan .jsx o también .js.", noShuffle:false },
  { concept_id:"dwec_u1_q23", unit:1, question:"¿Por qué se recomienda colocar las etiquetas <script> al final del <body>?", options:["Por convención estética","Para que el HTML se muestre antes de que el JS bloquee el renderizado","Porque si va en <head> produce errores","Para que el JS se ejecute más rápido"], correct:1, explanation:"Si el <script> está en el <head> sin defer/async, bloquea el parseo del HTML hasta que descarga y ejecuta el script.", noShuffle:false },
  { concept_id:"dwec_u1_q24", unit:1, question:"¿Qué es Babel en el ecosistema de JavaScript?", options:["Un gestor de paquetes de JS","Un transpilador que convierte JS moderno (ES6+) en JS compatible con navegadores más antiguos","Un framework de testing para JS","Un servidor web para proyectos JS"], correct:1, explanation:"Babel permite usar las últimas características de ES2022+ y lo convierte en ES5 que entienden navegadores antiguos.", noShuffle:false },
  { concept_id:"dwec_u1_q25", unit:1, question:"¿Qué significa 'DOM' en el contexto web?", options:["Data Object Model","Document Object Model","Dynamic Output Module","Design Object Method"], correct:1, explanation:"DOM (Document Object Model) es la representación en árbol del documento HTML que JS puede leer y manipular.", noShuffle:false },
  { concept_id:"dwec_u1_q26", unit:1, question:"¿Qué propiedad del objeto window muestra la URL actual de la página?", options:["window.href","window.location.href","window.url","window.address"], correct:1, explanation:"window.location es el objeto que representa la URL actual. location.href es la URL completa, location.pathname solo la ruta.", noShuffle:false },
  { concept_id:"dwec_u1_q27", unit:1, question:"¿Qué sucede si se incluye JavaScript con la etiqueta <script type='module'>?", options:["Solo funciona en IE11","El script tiene su propio ámbito, soporta import/export y se ejecuta en modo estricto automáticamente","El script se carga de forma síncrona","No se puede usar con CDN"], correct:1, explanation:"Los modules JS tienen ámbito propio (no añaden variables al global), usan import/export y aplican 'use strict' automáticamente.", noShuffle:false },
  { concept_id:"dwec_u1_q28", unit:1, question:"¿Qué es npm en el ecosistema JavaScript?", options:["Node Package Manager: gestor de paquetes para instalar librerías de Node.js/JavaScript","Un framework web de JavaScript","Un transpilador de TypeScript","Un motor de JavaScript alternativo"], correct:0, explanation:"npm gestiona paquetes JS (librerías, frameworks, herramientas). El fichero package.json declara las dependencias del proyecto.", noShuffle:false },
  { concept_id:"dwec_u1_q29", unit:1, question:"¿Cuál es la diferencia principal entre los frameworks Angular, React y Vue?", options:["Solo hay diferencias de precio","Son enfoques distintos para construir interfaces web: Angular es un framework completo; React una librería de UI; Vue un framework progresivo","Solo funcionan en distintos navegadores","No hay diferencia funcional entre ellos"], correct:1, explanation:"Angular (Google) = framework MVC completo. React (Meta) = librería de UI (solo la V de MVC). Vue = framework progresivo más ligero.", noShuffle:false },
  { concept_id:"dwec_u1_q30", unit:1, question:"¿Qué herramienta de las DevTools muestra el tiempo de carga de cada recurso (imágenes, JS, CSS)?", options:["Console","Sources","Network","Performance"], correct:2, explanation:"El panel Network de las DevTools muestra todas las peticiones HTTP, sus tamaños, tiempos y códigos de estado.", noShuffle:false },
  { concept_id:"dwec_u1_q31", unit:1, question:"¿Cómo se accede al objeto global en un navegador web?", options:["global","globalThis o window","self","document"], correct:1, explanation:"En navegadores, el objeto global es window. globalThis es el acceso estándar universal (funciona también en Node.js y Workers).", noShuffle:false },
  { concept_id:"dwec_u1_q32", unit:1, question:"¿Qué hace 'use strict' al inicio de un fichero o función JS?", options:["Acelera la ejecución del código JS","Activa el modo estricto que lanza errores para prácticas problemáticas (variables no declaradas, etc.)","Importa módulos estrictos de ES6","Deshabilita el tipado dinámico"], correct:1, explanation:"El modo estricto (ECMAScript 5) previene malas prácticas: no permite variables no declaradas, this undefined en funciones, etc.", noShuffle:false },
  { concept_id:"dwec_u1_q33", unit:1, question:"¿Qué es un polyfill en JavaScript?", options:["Una librería de animaciones CSS","Código que implementa una función o API moderna en navegadores que no la soportan nativamente","Una herramienta de bundling como Webpack","Un tipo de plugin para el navegador"], correct:1, explanation:"Los polyfills permiten usar APIs modernas en navegadores antiguos. Ej: el polyfill de fetch() para IE11.", noShuffle:false },
  { concept_id:"dwec_u1_q34", unit:1, question:"¿Qué característica de JavaScript permite que el lenguaje sea 'débilmente tipado'?", options:["Que las variables solo pueden almacenar números","Que las conversiones de tipo ocurren automáticamente sin errores en muchos casos (coerción de tipos)","Que el código no puede ejecutarse con errores","Que todas las variables son de tipo string"], correct:1, explanation:"La coerción de tipos convierte automáticamente valores entre tipos. Ej: '5' + 3 = '53' (concatenación). Puede ser fuente de bugs.", noShuffle:false },
  { concept_id:"dwec_u1_q35", unit:1, question:"¿Qué devuelve '5' + 3 en JavaScript?", options:["8","53","'53'","Error de tipo"], correct:2, explanation:"El operador + con un string produce concatenación. '5' + 3 convierte 3 a string y concatena → '53'.", noShuffle:false },
  { concept_id:"dwec_u1_q36", unit:1, question:"¿Qué es el event loop en JavaScript?", options:["Un bucle for que recorre eventos del DOM","El mecanismo que permite a JS (monohilo) gestionar operaciones asíncronas sin bloquear la ejecución","Una librería de gestión de eventos","El ciclo de vida de un componente React"], correct:1, explanation:"El event loop monitoriza la call stack y la callback queue. Cuando la stack está vacía, mueve las callbacks al stack para ejecutarlas.", noShuffle:false },
  { concept_id:"dwec_u1_q37", unit:1, question:"¿Qué es el 'call stack' en JavaScript?", options:["Una pila de llamadas que rastrea qué función se está ejecutando actualmente","Una estructura de datos para gestionar eventos del DOM","El historial de navegación del navegador","Un array especial de JavaScript"], correct:0, explanation:"La call stack es una estructura LIFO (last in, first out) que registra las funciones activas. Stack overflow = demasiadas llamadas anidadas.", noShuffle:false },
  { concept_id:"dwec_u1_q38", unit:1, question:"¿Cuál es el método correcto para seleccionar todos los elementos <p> de una página?", options:["document.getAll('p')","document.querySelectorAll('p')","document.findAll('p')","window.select('p')"], correct:1, explanation:"querySelectorAll() acepta cualquier selector CSS y devuelve una NodeList estática. Para p: document.querySelectorAll('p').", noShuffle:false },
  { concept_id:"dwec_u1_q39", unit:1, question:"¿Qué diferencia hay entre null y undefined en JavaScript?", options:["Son exactamente lo mismo","null es asignación intencional de 'sin valor'; undefined es ausencia de valor no inicializado","null solo existe en ES6+; undefined es más antiguo","undefined es un número especial; null es un objeto"], correct:1, explanation:"undefined: variable declarada pero no asignada, o parámetro no pasado. null: valor nulo asignado explícitamente por el programador.", noShuffle:false },
  { concept_id:"dwec_u1_q40", unit:1, question:"¿Qué muestra alert('Hola') en el navegador?", options:["Un mensaje en la consola","Una ventana modal de alerta con el texto 'Hola'","Un elemento HTML con el texto","Un log en el servidor"], correct:1, explanation:"alert() muestra una ventana modal del navegador que bloquea la ejecución hasta que el usuario hace clic en Aceptar.", noShuffle:false },
  { concept_id:"dwec_u1_q41", unit:1, question:"¿Cuál es la diferencia entre prompt() y confirm() en JavaScript?", options:["Son idénticos","prompt() solicita texto al usuario; confirm() muestra OK/Cancelar y devuelve booleano","confirm() es para números; prompt() para texto","prompt() está deprecated; confirm() no"], correct:1, explanation:"prompt(msg, default) → string o null. confirm(msg) → true/false. alert() solo muestra, sin retorno útil.", noShuffle:false },
  { concept_id:"dwec_u1_q42", unit:1, question:"¿Qué es Webpack?", options:["Un servidor web de alta velocidad","Un bundler que agrupa módulos JS y sus dependencias en uno o varios ficheros para producción","Un framework CSS para proyectos JS","Un motor de JavaScript para Node.js"], correct:1, explanation:"Webpack (y alternativas como Vite, Rollup, Parcel) agrupan el código JS moderno en bundles optimizados para el navegador.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 2 — Sintaxis del lenguaje JavaScript
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dwec_u2_q1", unit:2, question:"¿Cuál es la diferencia entre let y var en JavaScript?", options:["let permite más datos que var","let tiene ámbito de bloque; var tiene ámbito de función","var es más moderno que let","Son sinónimos"], correct:1, explanation:"let tiene ámbito de bloque ({}). var tiene ámbito de función y es elevada (hoisting). let evita muchos bugs de var.", noShuffle:false },
  { concept_id:"dwec_u2_q2", unit:2, question:"¿Qué devuelve el operador === en JavaScript?", options:["Compara solo el valor","Compara valor Y tipo (igualdad estricta)","Asigna el valor","Es el operador de identidad en memoria"], correct:1, explanation:"=== es igualdad estricta: compara valor y tipo. '5'===5 → false. == permite coerción: '5'==5 → true.", noShuffle:false },
  { concept_id:"dwec_u2_q3", unit:2, question:"¿Cuál es el resultado de typeof null en JavaScript?", options:["'null'","'undefined'","'object'","'boolean'"], correct:2, explanation:"typeof null devuelve 'object'. Es un bug histórico de JS mantenido por retrocompatibilidad.", noShuffle:false },
  { concept_id:"dwec_u2_q4", unit:2, question:"¿Cuáles son los tipos primitivos de JavaScript (ES2024)?", options:["number, string, boolean, null, undefined, symbol, bigint","int, float, string, boolean, char","number, string, boolean, array, object","integer, decimal, text, true/false"], correct:0, explanation:"7 tipos primitivos: number, string, boolean, null, undefined, symbol (ES6), bigint (ES2020). Arrays y objetos son de referencia.", noShuffle:false },
  { concept_id:"dwec_u2_q5", unit:2, question:"¿Qué estructura de control evalúa múltiples casos de una expresión?", options:["if-else","for...of","switch","try-catch"], correct:2, explanation:"switch evalúa una expresión y ejecuta el case coincidente. Requiere break para no caer en el siguiente case.", noShuffle:false },
  { concept_id:"dwec_u2_q6", unit:2, question:"¿Qué hace el bucle for...of en JavaScript?", options:["Itera sobre propiedades de un objeto","Itera sobre los VALORES de un iterable (array, string, Map...)","Ejecuta mientras una condición sea verdadera","Bucle con contador clásico"], correct:1, explanation:"for...of itera sobre valores de iterables. for...in itera sobre las claves/índices. Son conceptualmente distintos.", noShuffle:false },
  { concept_id:"dwec_u2_q7", unit:2, question:"¿Cuándo se ejecuta el bloque 'finally' en try-catch-finally?", options:["Solo si el try no tiene errores","Solo si hay un error","Siempre, con o sin error","Solo si el catch maneja el error"], correct:2, explanation:"finally siempre se ejecuta: útil para liberar recursos (cerrar conexiones, ocultar spinners, etc.).", noShuffle:false },
  { concept_id:"dwec_u2_q8", unit:2, question:"¿Qué es el 'hoisting' en JavaScript?", options:["Compresión del código JS","Un error con variables no declaradas","Las declaraciones var y function se 'elevan' al inicio de su ámbito durante la compilación","Carga asíncrona de scripts"], correct:2, explanation:"var y function declarations son elevadas (hoisted). let/const también se elevan pero no se inicializan (Temporal Dead Zone).", noShuffle:false },
  { concept_id:"dwec_u2_q9", unit:2, question:"¿Qué hace el operador ternario en JavaScript?", options:["Realiza una operación con tres números","Es una forma abreviada de if-else: condición ? valorSiTrue : valorSiFalse","Opera sobre tres arrays a la vez","No existe en JavaScript"], correct:1, explanation:"El ternario: const resultado = edad >= 18 ? 'adulto' : 'menor'. Es conciso pero no debe anidarse en exceso.", noShuffle:false },
  { concept_id:"dwec_u2_q10", unit:2, question:"¿Cuál es el resultado de 10 % 3 en JavaScript?", options:["3","3.33","1","0"], correct:2, explanation:"El operador % devuelve el resto de la división entera. 10 / 3 = 3 resto 1, por tanto 10 % 3 = 1.", noShuffle:false },
  { concept_id:"dwec_u2_q11", unit:2, question:"¿Qué diferencia hay entre i++ y ++i?", options:["Son idénticos","i++ devuelve el valor ANTES de incrementar; ++i incrementa PRIMERO y devuelve el nuevo valor","++i solo existe en C, no en JavaScript","i++ suma 2; ++i suma 1"], correct:1, explanation:"Post-incremento (i++): devuelve i y luego incrementa. Pre-incremento (++i): incrementa y devuelve el nuevo valor.", noShuffle:false },
  { concept_id:"dwec_u2_q12", unit:2, question:"¿Qué devuelve Boolean('') en JavaScript?", options:["true","false","null","undefined"], correct:1, explanation:"Los valores falsy en JS son: false, 0, -0, 0n, '', null, undefined, NaN. Una cadena vacía es falsy.", noShuffle:false },
  { concept_id:"dwec_u2_q13", unit:2, question:"¿Cuál es la diferencia entre el operador && y || en JS?", options:["&& devuelve true/false siempre; || devuelve strings","&& devuelve el primer falsy o el último valor; || devuelve el primer truthy o el último valor","No hay diferencia lógica entre ellos","&& es para números; || para strings"], correct:1, explanation:"Short-circuit evaluation: [] && b → b (si [] es truthy). false || 'default' → 'default'. Útil para valores por defecto.", noShuffle:false },
  { concept_id:"dwec_u2_q14", unit:2, question:"¿Qué es el operador de coalescencia nula (??) en JavaScript?", options:["Comprueba si un valor es null o undefined y devuelve el operando derecho en ese caso","Es equivalente al operador OR (||)","Comprueba si dos objetos son iguales","Crea una copia nula de un objeto"], correct:0, explanation:"?? solo activa el valor por defecto si el lado izquierdo es null o undefined, no para otros falsy (0, ''). Disponible desde ES2020.", noShuffle:false },
  { concept_id:"dwec_u2_q15", unit:2, question:"¿Qué hace la instrucción 'break' dentro de un switch?", options:["Sale del script completo","Termina la ejecución del case actual y sale del switch","Pasa al siguiente case","Reinicia el switch"], correct:1, explanation:"Sin break, la ejecución continúa en el siguiente case (fall-through). break es necesario salvo que quieras ese comportamiento.", noShuffle:false },
  { concept_id:"dwec_u2_q16", unit:2, question:"¿Qué hace 'continue' dentro de un bucle?", options:["Sale completamente del bucle","Salta a la siguiente iteración del bucle","Reinicia el bucle desde el principio","Genera un error"], correct:1, explanation:"continue omite el resto del cuerpo del bucle para esa iteración y pasa directamente a la siguiente evaluación de la condición.", noShuffle:false },
  { concept_id:"dwec_u2_q17", unit:2, question:"¿Cuál es la forma correcta de lanzar un error personalizado en JavaScript?", options:["error('Mi error')","throw new Error('Mi error')","raise Error('Mi error')","exception('Mi error')"], correct:1, explanation:"throw lanza una excepción. Se puede lanzar cualquier valor, pero se recomienda throw new Error('mensaje') para obtener stack trace.", noShuffle:false },
  { concept_id:"dwec_u2_q18", unit:2, question:"¿Qué es NaN en JavaScript?", options:["El número 0","El valor 'No a Number': resultado de operaciones numéricas inválidas","null de tipo numérico","Una constante igual a infinito"], correct:1, explanation:"NaN (Not a Number) resulta de operaciones como 0/0, parseInt('hola'). Curiosamente, typeof NaN === 'number' y NaN !== NaN.", noShuffle:false },
  { concept_id:"dwec_u2_q19", unit:2, question:"¿Cómo se comprueba si un valor es NaN de forma fiable?", options:["valor === NaN","valor == NaN","Number.isNaN(valor)","isNan(valor)"], correct:2, explanation:"Number.isNaN() es preciso. La función global isNaN() convierte antes a número: isNaN('hola') → true, Number.isNaN('hola') → false.", noShuffle:false },
  { concept_id:"dwec_u2_q20", unit:2, question:"¿Cuál es la diferencia entre for...in y for...of?", options:["for...in itera sobre índices de arrays; for...of sobre propiedades de objetos","for...in itera sobre las CLAVES/propiedades enumerables; for...of itera sobre los VALORES de iterables","Son equivalentes, solo difieren en sintaxis","for...in es más moderno que for...of"], correct:1, explanation:"for...in: claves de objeto. for...of: valores de iterables. Usar for...in sobre arrays puede dar resultados inesperados si el array tiene propiedades extras.", noShuffle:false },
  { concept_id:"dwec_u2_q21", unit:2, question:"¿Qué devuelve parseInt('10.5px', 10)?", options:["10.5","10","NaN","'10'"], correct:1, explanation:"parseInt parsea hasta que encuentra un carácter no numérico. '10.5px' → 10. El segundo argumento es la base (10 = decimal).", noShuffle:false },
  { concept_id:"dwec_u2_q22", unit:2, question:"¿Qué es el operador de encadenamiento opcional (?.) en JavaScript?", options:["Una forma de crear cadenas de texto condicionales","Permite acceder a propiedades de objetos que pueden ser null/undefined sin lanzar error","Es equivalente al operador ternario","Concatena strings de forma segura"], correct:1, explanation:"obj?.prop devuelve undefined en lugar de lanzar TypeError si obj es null/undefined. obj?.method?.() para llamadas a métodos.", noShuffle:false },
  { concept_id:"dwec_u2_q23", unit:2, question:"¿Cuál es el operador de exponenciación en JavaScript (ES2016)?", options:["Math.pow()","^","**","^^"], correct:2, explanation:"El operador ** es la exponenciación: 2 ** 10 = 1024. Math.pow(2,10) hace lo mismo pero es más verboso.", noShuffle:false },
  { concept_id:"dwec_u2_q24", unit:2, question:"¿Qué es un template literal (template string) en JavaScript?", options:["Una función que genera strings","Strings delimitados por backticks (`) que permiten interpolación con ${expresión} y multilínea","Una librería para formatear strings","Strings con caracteres especiales escapados"], correct:1, explanation:"Template literals: `Hola ${nombre}`. Permiten multilínea sin \\n y expresiones JS dentro de ${}.", noShuffle:false },
  { concept_id:"dwec_u2_q25", unit:2, question:"¿Qué sucede si se accede a una variable let antes de su declaración?", options:["Devuelve undefined como var","Lanza un ReferenceError (Temporal Dead Zone)","El intérprete la declara automáticamente","Devuelve null"], correct:1, explanation:"let y const están en la Temporal Dead Zone (TDZ) desde el inicio del bloque hasta su declaración. Acceder antes lanza ReferenceError.", noShuffle:false },
  { concept_id:"dwec_u2_q26", unit:2, question:"¿Qué devuelve typeof function(){}?", options:["'object'","'function'","'callable'","'undefined'"], correct:1, explanation:"typeof devuelve 'function' para funciones. Aunque las funciones son objetos en JS, typeof hace una distinción especial para ellas.", noShuffle:false },
  { concept_id:"dwec_u2_q27", unit:2, question:"¿Cuál es el resultado de [] == false en JavaScript?", options:["true","false","TypeError","undefined"], correct:0, explanation:"Por coerción: [] → '' (toString) → 0 (Number) → false == false → true. La coerción de tipos puede dar resultados sorprendentes.", noShuffle:false },
  { concept_id:"dwec_u2_q28", unit:2, question:"¿Para qué sirve la palabra clave 'in' en JavaScript?", options:["Para importar módulos","Comprueba si una propiedad existe en un objeto o si un índice existe en un array","Para iterar sobre arrays","Para comparar dos objetos"], correct:1, explanation:"'key' in objeto → true/false. Tambén: 0 in [1,2,3] → true. Comprueba propiedades propias Y heredadas.", noShuffle:false },
  { concept_id:"dwec_u2_q29", unit:2, question:"¿Qué diferencia hay entre declarar una función con function y con una arrow function?", options:["Solo sintáctica, son completamente equivalentes","Las arrow functions no tienen su propio 'this', 'arguments' ni pueden usarse como constructores","Las funciones clásicas son más lentas","Las arrow functions no pueden devolver valores"], correct:1, explanation:"Diferencias clave: 1) Arrow functions heredan this del contexto léxico. 2) No tienen objeto arguments. 3) No se pueden usar con new.", noShuffle:false },
  { concept_id:"dwec_u2_q30", unit:2, question:"¿Qué devuelve 0.1 + 0.2 === 0.3 en JavaScript?", options:["true","false","NaN","TypeError"], correct:1, explanation:"false. Los números flotantes en JS (IEEE 754) tienen imprecisión: 0.1+0.2 = 0.30000000000000004. Comparar con tolerancia: Math.abs(a-b) < 1e-9.", noShuffle:false },
  { concept_id:"dwec_u2_q31", unit:2, question:"¿Cuál es el resultado de '3' * 2 en JavaScript?", options:["'32'","6","'6'","NaN"], correct:1, explanation:"El operador * no tiene sobrecarga de string: convierte '3' a número → 6. Solo + produce concatenación con strings.", noShuffle:false },
  { concept_id:"dwec_u2_q32", unit:2, question:"¿Qué es la Temporal Dead Zone (TDZ) en JavaScript?", options:["Una zona de memoria reservada para variables globales","El período entre el inicio del bloque y la declaración de let/const donde la variable existe pero no se puede usar","Un tipo especial de ámbito en módulos ES6","El tiempo que tarda el navegador en ejecutar un script"], correct:1, explanation:"En la TDZ, la variable está declarada a nivel léxico pero no inicializada. Cualquier acceso lanza ReferenceError.", noShuffle:false },
  { concept_id:"dwec_u2_q33", unit:2, question:"¿Qué hace Object.freeze() en JavaScript?", options:["Congela el tiempo de ejecución del script","Hace que un objeto sea inmutable: no se pueden añadir, eliminar ni modificar propiedades","Serializa el objeto a JSON","Hace una copia profunda del objeto"], correct:1, explanation:"Object.freeze(obj) previene modificaciones al objeto. Es 'shallow': los objetos anidados no se congelan automáticamente.", noShuffle:false },
  { concept_id:"dwec_u2_q34", unit:2, question:"¿Cuántos bytes ocupa un número (Number) en JavaScript?", options:["4 bytes (32-bit int)","8 bytes (64-bit double precision float)","2 bytes (16-bit)","Depende del valor"], correct:1, explanation:"Todos los numbers en JS son IEEE 754 double precision (64 bits = 8 bytes). Para enteros grandes se usa BigInt.", noShuffle:false },
  { concept_id:"dwec_u2_q35", unit:2, question:"¿Qué operador se usa para saber si un objeto es instancia de una clase?", options:["typeof","instanceof","istype()","classof()"], correct:1, explanation:"instanceof comprueba si el objeto fue creado con un constructor dado: perro instanceof Animal → true/false.", noShuffle:false },
  { concept_id:"dwec_u2_q36", unit:2, question:"¿Qué hace el método String.trim() en JavaScript?", options:["Elimina caracteres del medio del string","Elimina los espacios en blanco al inicio y al final del string","Acorta el string a N caracteres","Convierte el string a minúsculas"], correct:1, explanation:"trim() elimina espacios, tabuladores y saltos de línea al inicio y final. trimStart() y trimEnd() son versiones unilaterales.", noShuffle:false },
  { concept_id:"dwec_u2_q37", unit:2, question:"¿Qué devuelve 'javascript'.toUpperCase()?", options:["'JAVASCRIPT'","'Javascript'","Error: método no existe","'javascript'"], correct:0, explanation:"toUpperCase() convierte todos los caracteres a mayúsculas. toLowerCase() hace lo contrario. Ambos devuelven una nueva cadena.", noShuffle:false },
  { concept_id:"dwec_u2_q38", unit:2, question:"¿Cuál es el valor máximo seguro para un entero en JavaScript (Number.MAX_SAFE_INTEGER)?", options:["2^31 - 1 = 2.147.483.647","2^53 - 1 = 9.007.199.254.740.991","Infinity","2^64 - 1"], correct:1, explanation:"Number.MAX_SAFE_INTEGER = 2^53-1 ≈ 9 cuatrillones. Para enteros mayores sin pérdida de precisión se usa BigInt.", noShuffle:false },
  { concept_id:"dwec_u2_q39", unit:2, question:"¿Cómo se convierte un número a string en JavaScript?", options:["String(num) o num.toString()","str(num)","num.stringify()","parseString(num)"], correct:0, explanation:"String(42) → '42'. (42).toString() → '42'. (42).toString(2) → '101010' (binario). Los tres son equivalentes pero String() es más robusto.", noShuffle:false },
  { concept_id:"dwec_u2_q40", unit:2, question:"¿Qué es el operador de asignación lógica &&= en JavaScript (ES2021)?", options:["Asigna solo si el lado izquierdo es falsy","Asigna solo si el lado izquierdo es truthy: a &&= b equivale a a && (a = b)","Compara y asigna en un paso","No existe en JavaScript"], correct:1, explanation:"a &&= b: si a es truthy, asigna b a a. ||= asigna si es falsy. ??= asigna si es null/undefined. Disponibles desde ES2021.", noShuffle:false },
  { concept_id:"dwec_u2_q41", unit:2, question:"¿Qué devuelve typeof undefined?", options:["'null'","'object'","'undefined'","'void'"], correct:2, explanation:"typeof undefined === 'undefined'. Es uno de los pocos casos donde typeof no lanza error aunque la variable no esté declarada.", noShuffle:false },
  { concept_id:"dwec_u2_q42", unit:2, question:"¿Qué hace el operador de propagación opcional (?.) al llamar un método?", options:["Lanza un error si el objeto no tiene el método","Llama al método solo si el objeto y el método existen, retorna undefined si no","Crea el método si no existe","Es equivalente a try-catch"], correct:1, explanation:"obj?.metodo?.() evita TypeError en cadenas de acceso a propiedades potencialmente nullish. Muy útil en manejo de respuestas de API.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 3 — Objetos predefinidos de JavaScript
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dwec_u3_q1", unit:3, question:"¿Qué método del objeto Array elimina y devuelve el ÚLTIMO elemento?", options:["shift()","pop()","splice()","slice()"], correct:1, explanation:"pop() → último elemento. shift() → primero. push() añade al final. unshift() añade al principio.", noShuffle:false },
  { concept_id:"dwec_u3_q2", unit:3, question:"¿Qué devuelve Math.floor(4.9)?", options:["5","4","4.9","Error"], correct:1, explanation:"Math.floor() redondea hacia abajo. Math.ceil() hacia arriba. Math.round() al más cercano. Math.trunc() elimina decimales.", noShuffle:false },
  { concept_id:"dwec_u3_q3", unit:3, question:"¿Qué hace Array.filter()?", options:["Transforma cada elemento","Busca el índice del primer elemento coincidente","Devuelve un nuevo array con elementos que cumplen la condición","Ordena el array"], correct:2, explanation:"filter(fn) devuelve un NUEVO array con los elementos para los que fn retorna true. No modifica el original.", noShuffle:false },
  { concept_id:"dwec_u3_q4", unit:3, question:"¿Qué objeto de JS representa la ventana del navegador y es el objeto global?", options:["document","navigator","window","screen"], correct:2, explanation:"window es el objeto global. Todas las variables globales son propiedades de window. document, navigator, screen son propiedades de window.", noShuffle:false },
  { concept_id:"dwec_u3_q5", unit:3, question:"¿Cómo se genera un número aleatorio entre 0 (inclusive) y 1 (exclusive)?", options:["Math.random()","Math.rand()","Number.random()","window.random()"], correct:0, explanation:"Math.random() → [0, 1). Para [min, max]: Math.floor(Math.random()*(max-min+1))+min.", noShuffle:false },
  { concept_id:"dwec_u3_q6", unit:3, question:"¿Qué método de String devuelve la posición de la primera ocurrencia de una subcadena?", options:["search()","find()","indexOf()","position()"], correct:2, explanation:"indexOf() → primer índice o -1. lastIndexOf() → último. includes() → boolean. startsWith()/endsWith() → boolean.", noShuffle:false },
  { concept_id:"dwec_u3_q7", unit:3, question:"¿Qué hace Array.map()?", options:["Elimina duplicados","Aplica una función a cada elemento y devuelve un nuevo array con los resultados","Combina dos arrays","Devuelve el mayor elemento"], correct:1, explanation:"map() transforma cada elemento: [1,2,3].map(x=>x*2) → [2,4,6]. No modifica el original.", noShuffle:false },
  { concept_id:"dwec_u3_q8", unit:3, question:"¿Qué devuelve Array.find(fn)?", options:["Un array con todos los elementos que cumplen la condición","El PRIMER elemento que cumple la condición, o undefined","El índice del primer elemento","true/false"], correct:1, explanation:"find() devuelve el VALOR del primer elemento que satisface fn. findIndex() devuelve el ÍNDICE.", noShuffle:false },
  { concept_id:"dwec_u3_q9", unit:3, question:"¿Qué hace Array.some(fn)?", options:["Verifica que TODOS los elementos cumplan la condición","Verifica que AL MENOS UNO cumpla la condición","Suma todos los elementos","Ejecuta fn para cada elemento sin retorno"], correct:1, explanation:"some() → true si al menos uno pasa la prueba. every() → true solo si TODOS pasan. Ambos son atajos de reduce.", noShuffle:false },
  { concept_id:"dwec_u3_q10", unit:3, question:"¿Qué hace Array.every(fn)?", options:["Ejecuta fn una sola vez","Devuelve true solo si TODOS los elementos cumplen la condición","Devuelve el número de elementos","Verifica si el array está vacío"], correct:1, explanation:"every() → true si fn retorna true para TODOS los elementos. En cuanto uno falla, para (short-circuit).", noShuffle:false },
  { concept_id:"dwec_u3_q11", unit:3, question:"¿Cómo se ordena un array de números de forma ascendente?", options:["arr.sort()","arr.sort((a,b) => a - b)","arr.order()","arr.ascending()"], correct:1, explanation:"sort() sin argumento ordena como strings ('10'<'9'). Para números: sort((a,b)=>a-b) ascendente; sort((a,b)=>b-a) descendente.", noShuffle:false },
  { concept_id:"dwec_u3_q12", unit:3, question:"¿Qué hace Array.flat()?", options:["Aplana el array eliminando elementos falsy","Aplana arrays anidados a un nivel por defecto (o al nivel especificado)","Convierte el array a string","Ordena el array"], correct:1, explanation:"[1,[2,[3]]].flat() → [1,2,[3]]. flat(Infinity) aplana completamente. flatMap() combina map+flat(1).", noShuffle:false },
  { concept_id:"dwec_u3_q13", unit:3, question:"¿Qué devuelve Array.includes(valor)?", options:["El índice del valor","true si el valor está en el array, false si no","Un array con solo ese valor","NaN si no se encuentra"], correct:1, explanation:"includes() usa igualdad estricta y distingue NaN correctamente (a diferencia de indexOf que usa ===).", noShuffle:false },
  { concept_id:"dwec_u3_q14", unit:3, question:"¿Qué hace el método String.split(separador)?", options:["Divide el string en caracteres individuales siempre","Divide el string en un array de partes usando el separador","Elimina el separador del string","Ordena el string"], correct:1, explanation:"'a,b,c'.split(',') → ['a','b','c']. Sin argumento: el string completo. Con '' → caracteres individuales.", noShuffle:false },
  { concept_id:"dwec_u3_q15", unit:3, question:"¿Qué método de Array une todos sus elementos en un string?", options:["toString()","concat()","join(separador)","combine()"], correct:2, explanation:"join() une los elementos con el separador dado: ['a','b','c'].join('-') → 'a-b-c'. join() sin argumento usa coma.", noShuffle:false },
  { concept_id:"dwec_u3_q16", unit:3, question:"¿Qué hace Object.keys(obj)?", options:["Devuelve el número de propiedades","Devuelve un array con los nombres de las propiedades propias enumerables del objeto","Comprueba si el objeto tiene propiedades","Elimina todas las propiedades"], correct:1, explanation:"Object.keys() → array de claves propias. Object.values() → array de valores. Object.entries() → array de [clave, valor].", noShuffle:false },
  { concept_id:"dwec_u3_q17", unit:3, question:"¿Cómo se crea un array con 5 posiciones inicializadas a 0?", options:["new Array(5).fill(0)","Array(5).map(()=>0)","[0,0,0,0,0]","Array.create(5, 0)"], correct:0, explanation:"new Array(5) crea un array de 5 posiciones vacías. .fill(0) las inicializa a 0. También: Array.from({length:5}, ()=>0).", noShuffle:false },
  { concept_id:"dwec_u3_q18", unit:3, question:"¿Qué devuelve Math.max(1, 5, 3, 9, 2)?", options:["1","9","5","NaN"], correct:1, explanation:"Math.max() devuelve el mayor. Math.min() el menor. Para arrays: Math.max(...arr) o Math.max.apply(null, arr).", noShuffle:false },
  { concept_id:"dwec_u3_q19", unit:3, question:"¿Cómo se obtiene la longitud de un string en JavaScript?", options:["string.length()","string.length","string.size()","string.count"], correct:1, explanation:"length es una propiedad (no método) de strings y arrays. No lleva paréntesis.", noShuffle:false },
  { concept_id:"dwec_u3_q20", unit:3, question:"¿Qué hace String.slice(inicio, fin)?", options:["Elimina caracteres del string original","Devuelve una subcadena sin modificar el original; acepta índices negativos","Divide el string en partes iguales","Reemplaza una subcadena"], correct:1, explanation:"slice(2,5) extrae posiciones 2,3,4. Con negativo: 'hola'.slice(-2) → 'la'. substring() es similar pero no acepta negativos.", noShuffle:false },
  { concept_id:"dwec_u3_q21", unit:3, question:"¿Qué hace el método Date.now()?", options:["Devuelve la fecha actual en formato legible","Devuelve el timestamp actual en milisegundos desde el 1 de enero de 1970 (Unix Epoch)","Crea un nuevo objeto Date","Formatea la fecha actual"], correct:1, explanation:"Date.now() es equivalente a new Date().getTime(). Útil para medir tiempos de ejecución: const t0=Date.now(); ... console.log(Date.now()-t0).", noShuffle:false },
  { concept_id:"dwec_u3_q22", unit:3, question:"¿Qué devuelve new Date().getMonth() para enero?", options:["1","0","'January'","'Enero'"], correct:1, explanation:"getMonth() devuelve 0-11 (no 1-12). Enero=0, Diciembre=11. getFullYear(), getDate(), getHours(), getMinutes(), getSeconds() funcionan como esperarías.", noShuffle:false },
  { concept_id:"dwec_u3_q23", unit:3, question:"¿Qué hace Array.concat()?", options:["Convierte el array a string","Une dos o más arrays en uno nuevo sin modificar los originales","Elimina elementos repetidos","Aplana arrays anidados"], correct:1, explanation:"[1,2].concat([3,4],[5]) → [1,2,3,4,5]. No modifica los originales. El spread [...a,...b] logra lo mismo.", noShuffle:false },
  { concept_id:"dwec_u3_q24", unit:3, question:"¿Qué hace String.replace(búsqueda, reemplazo)?", options:["Reemplaza TODAS las ocurrencias por defecto","Reemplaza solo la PRIMERA ocurrencia (si búsqueda es string); con regex /g reemplaza todas","Elimina la subcadena del string","Inserta el reemplazo al inicio"], correct:1, explanation:"'aaaa'.replace('a','b') → 'baaa'. Para reemplazar todas: 'aaaa'.replaceAll('a','b') o 'aaaa'.replace(/a/g,'b').", noShuffle:false },
  { concept_id:"dwec_u3_q25", unit:3, question:"¿Qué método comprueba si un string cumple una expresión regular?", options:["regex.test(string)","string.match(regex)","string.search(regex)","Todos los anteriores"], correct:3, explanation:"test() → boolean. match() → array de coincidencias o null. search() → índice o -1. Todos funcionan, pero para un boolean simple, test() es el más directo.", noShuffle:false },
  { concept_id:"dwec_u3_q26", unit:3, question:"¿Qué es el prototipo de un objeto en JavaScript?", options:["El tipo de dato del objeto","El objeto del que hereda propiedades y métodos (mecanismo de herencia de JS)","Una copia de seguridad del objeto","La clase padre del objeto"], correct:1, explanation:"Prototype chain: si una propiedad no se encuentra en el objeto, JS busca en su prototipo, y así sucesivamente hasta Object.prototype.", noShuffle:false },
  { concept_id:"dwec_u3_q27", unit:3, question:"¿Qué hace el método Array.splice(inicio, cantidad)?", options:["Extrae elementos sin modificar el original","Elimina 'cantidad' elementos desde 'inicio' y los devuelve, modificando el original","Inserta elementos en el array","Ordena una parte del array"], correct:1, explanation:"splice() modifica el array original. splice(1,2) elimina 2 elementos desde índice 1. splice(1,0,'nuevo') inserta sin eliminar.", noShuffle:false },
  { concept_id:"dwec_u3_q28", unit:3, question:"¿Cuál es la diferencia entre Array.slice() y Array.splice()?", options:["slice modifica el original; splice no","splice modifica el original; slice devuelve una copia sin modificar","Son completamente equivalentes","slice acepta índices negativos; splice no"], correct:1, explanation:"slice(): inmutable, devuelve nueva copia. splice(): mutable, modifica el original Y devuelve los elementos eliminados.", noShuffle:false },
  { concept_id:"dwec_u3_q29", unit:3, question:"¿Qué hace JSON.parse(string)?", options:["Convierte un objeto JS a string JSON","Convierte un string JSON válido a un objeto/valor JavaScript","Valida si un string es JSON correcto","Formatea un JSON de forma legible"], correct:1, explanation:"JSON.parse() deserializa. JSON.stringify() serializa. Errores de parsing lanzan SyntaxError.", noShuffle:false },
  { concept_id:"dwec_u3_q30", unit:3, question:"¿Qué hace JSON.stringify(objeto, null, 2)?", options:["Parsea el JSON con 2 niveles de profundidad","Convierte el objeto a string JSON con indentación de 2 espacios (legible)","Filtra 2 propiedades del objeto","Crea 2 copias del JSON"], correct:1, explanation:"El tercer argumento de stringify() es el nivel de indentación para formato legible. null es el replacer (función de filtrado).", noShuffle:false },
  { concept_id:"dwec_u3_q31", unit:3, question:"¿Qué hace Object.assign(destino, ...fuentes)?", options:["Compara dos objetos","Copia las propiedades enumerables de las fuentes al objeto destino","Fusiona dos objetos en uno nuevo","Clona profundamente un objeto"], correct:1, explanation:"Object.assign() hace una copia shallow. Modifica el destino. Para no modificar el original: Object.assign({}, obj1, obj2).", noShuffle:false },
  { concept_id:"dwec_u3_q32", unit:3, question:"¿Cómo se clona un array de forma superficial (shallow copy)?", options:["[...arr] o arr.slice()","arr.clone()","JSON.parse(JSON.stringify(arr))","Object.copy(arr)"], correct:0, explanation:"Shallow copy: [...arr] o arr.slice(). Deep copy: structuredClone(arr) (moderno) o JSON.parse(JSON.stringify(arr)) (limitado).", noShuffle:false },
  { concept_id:"dwec_u3_q33", unit:3, question:"¿Qué devuelve Array.indexOf('b') sobre el array ['a','b','c','b']?", options:["1","[1,3]","-1","'b'"], correct:0, explanation:"indexOf() devuelve el índice de la PRIMERA ocurrencia: 1. lastIndexOf() devolvería 3. Retorna -1 si no se encuentra.", noShuffle:false },
  { concept_id:"dwec_u3_q34", unit:3, question:"¿Qué hace Math.abs(-7)?", options:["-7","7","0","Error"], correct:1, explanation:"Math.abs() devuelve el valor absoluto: Math.abs(-7)=7, Math.abs(7)=7.", noShuffle:false },
  { concept_id:"dwec_u3_q35", unit:3, question:"¿Para qué sirve el objeto Map en JavaScript?", options:["Para gestionar mapas geográficos","Para almacenar pares clave-valor donde las claves pueden ser de CUALQUIER tipo (no solo strings)","Para transformar arrays igual que Array.map()","Para definir plantillas de objetos"], correct:1, explanation:"Map permite claves de cualquier tipo (objetos, funciones...). A diferencia de los objetos, mantiene el orden de inserción.", noShuffle:false },
  { concept_id:"dwec_u3_q36", unit:3, question:"¿Para qué sirve el objeto Set en JavaScript?", options:["Para almacenar objetos con propiedades","Para almacenar valores únicos de cualquier tipo (sin duplicados)","Para crear conjuntos matemáticos con operaciones","Para gestionar estados de aplicaciones"], correct:1, explanation:"Set elimina duplicados automáticamente. new Set([1,2,2,3]) → {1,2,3}. Útil para deduplicar: [...new Set(array)].", noShuffle:false },
  { concept_id:"dwec_u3_q37", unit:3, question:"¿Qué devuelve Number.isInteger(4.0)?", options:["false","true","undefined","Error"], correct:1, explanation:"Number.isInteger(4.0) → true porque 4.0 es un entero en JS (no hay distinción entre int y float).", noShuffle:false },
  { concept_id:"dwec_u3_q38", unit:3, question:"¿Cuál es el resultado de Math.round(4.5)?", options:["4","5","4.5","NaN"], correct:1, explanation:"Math.round() redondea al entero más cercano; en caso de .5 redondea hacia arriba. Math.round(4.5)=5, Math.round(-4.5)=-4.", noShuffle:false },
  { concept_id:"dwec_u3_q39", unit:3, question:"¿Cómo se convierte una cadena a número entero en JavaScript?", options:["Number.parseInt('42')","parseInt('42') o Number('42')|0","'42' - 0 o +'42'","Todas las anteriores son válidas"], correct:3, explanation:"parseInt(), Number(), el operador unario + y la resta de 0 son formas válidas. parseInt('42px')→42; Number('42px')→NaN.", noShuffle:false },
  { concept_id:"dwec_u3_q40", unit:3, question:"¿Qué es el objeto navigator en JavaScript?", options:["Un router de páginas SPA","Objeto que expone información sobre el navegador y sistema del usuario (versión, idioma, geolocalización...)","El objeto que gestiona la navegación por el historial","Un objeto para peticiones HTTP"], correct:1, explanation:"navigator contiene: navigator.userAgent (info del navegador), navigator.language, navigator.online, navigator.geolocation, etc.", noShuffle:false },
  { concept_id:"dwec_u3_q41", unit:3, question:"¿Qué hace window.history.back()?", options:["Borra el historial del navegador","Navega a la página anterior del historial (equivalente al botón Atrás)","Mueve el historial hacia adelante","Recarga la página actual"], correct:1, explanation:"history.back() = history.go(-1). history.forward() = history.go(1). history.pushState() añade entradas sin recargar.", noShuffle:false },
  { concept_id:"dwec_u3_q42", unit:3, question:"¿Qué hace el método Array.reduce() con el array [1,2,3,4]?", options:["Reduce el tamaño del array a la mitad","Aplica una función acumuladora para reducir el array a un único valor","Filtra los elementos que no cumplen una condición","Busca el elemento mínimo"], correct:1, explanation:"[1,2,3,4].reduce((acc,n)=>acc+n, 0) → 10. El segundo argumento es el valor inicial del acumulador.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 4 — Funciones y programación funcional
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dwec_u4_q1", unit:4, question:"¿Qué es una función flecha (arrow function) en JavaScript?", options:["Una función que siempre devuelve un array","Sintaxis compacta para funciones que no tiene su propio 'this'","Un método específico de los arrays","Una función que solo puede tener un parámetro"], correct:1, explanation:"Arrow functions (=>) heredan this del contexto léxico, no tienen arguments propio y no pueden usarse con new.", noShuffle:false },
  { concept_id:"dwec_u4_q2", unit:4, question:"¿Qué es un closure (clausura) en JavaScript?", options:["Un error al cerrar una función sin return","Una función que accede y recuerda las variables de su ámbito léxico exterior","Un método para cerrar conexiones de red","La sintaxis para terminar un bucle"], correct:1, explanation:"El closure recuerda el entorno donde fue creado, incluyendo variables locales del scope padre, incluso después de que ese scope terminó.", noShuffle:false },
  { concept_id:"dwec_u4_q3", unit:4, question:"¿Para qué sirve el operador spread (...) en JavaScript?", options:["Para declarar variables sin valor","Para expandir un iterable en sus elementos individuales","Para concatenar cadenas","Para crear un bucle infinito"], correct:1, explanation:"Spread: fn(...args), [...arr1,...arr2], {...obj1,...obj2}. También se usa para clonar arrays y objetos superficialmente.", noShuffle:false },
  { concept_id:"dwec_u4_q4", unit:4, question:"¿Qué es la destructuración de arrays en JavaScript?", options:["Eliminar todos los elementos de un array","Convertir un array en un string","Asignar elementos de un array a variables individuales con sintaxis compacta","Invertir el orden del array"], correct:2, explanation:"const [a, b, c] = [1, 2, 3]. Se puede saltar: const [a,,c] = [1,2,3]. Y valor por defecto: const [a=0] = [].", noShuffle:false },
  { concept_id:"dwec_u4_q5", unit:4, question:"¿Qué hace Array.reduce()?", options:["Elimina el número de elementos indicado","Acumula todos los elementos en un único valor mediante una función reductora","Reduce el tamaño en bytes del array","Filtra eliminando los valores falsy"], correct:1, explanation:"[1,2,3].reduce((acc,n)=>acc+n, 0) → 6. El acumulador va pasando de iteración en iteración.", noShuffle:false },
  { concept_id:"dwec_u4_q6", unit:4, question:"¿Qué es la desestructuración de objetos en JavaScript?", options:["Eliminar propiedades de un objeto","Extraer propiedades de un objeto a variables individuales: const {nombre, edad} = persona","Comparar dos objetos","Convertir un objeto a array"], correct:1, explanation:"const {nombre, edad} = {nombre:'Ana', edad:25}. Se puede renombrar: const {nombre: n} = persona. Y con default: const {edad=18} = {}.", noShuffle:false },
  { concept_id:"dwec_u4_q7", unit:4, question:"¿Qué hace el parámetro rest (...params) en una función?", options:["Crea un bucle que repite la función","Captura los argumentos restantes en un array real","Es un alias del operador spread","Establece un valor por defecto para el último parámetro"], correct:1, explanation:"function fn(a, b, ...rest) — rest es un array con todos los argumentos a partir del tercero. A diferencia de arguments, rest es un array real.", noShuffle:false },
  { concept_id:"dwec_u4_q8", unit:4, question:"¿Qué es la programación funcional en JavaScript?", options:["Programar solo con funciones matemáticas","Un estilo de programación que trata las funciones como valores de primera clase, evita el estado mutable y los efectos secundarios","Un tipo de POO con funciones en lugar de clases","Programar sin usar variables"], correct:1, explanation:"FP se apoya en: funciones puras, inmutabilidad, composición de funciones, HOF (map, filter, reduce) y evitar efectos secundarios.", noShuffle:false },
  { concept_id:"dwec_u4_q9", unit:4, question:"¿Qué es una Higher-Order Function (HOF)?", options:["Una función que opera sobre números muy grandes","Una función que acepta otras funciones como argumentos y/o devuelve una función como resultado","Una función con alta prioridad de ejecución","Una función que solo puede ser llamada desde el ámbito global"], correct:1, explanation:"HOF: map, filter, reduce, sort, forEach... aceptan funciones como argumento. Una función que devuelve otra función también es HOF.", noShuffle:false },
  { concept_id:"dwec_u4_q10", unit:4, question:"¿Qué es la composición de funciones en programación funcional?", options:["Crear objetos con múltiples funciones","Combinar funciones simples para crear funciones más complejas: f(g(x))","Llamar múltiples funciones en paralelo","Compartir código entre funciones mediante herencia"], correct:1, explanation:"Composición: const compose = (f,g) => x => f(g(x)). Permite construir pipelines de transformación de datos legibles y testeables.", noShuffle:false },
  { concept_id:"dwec_u4_q11", unit:4, question:"¿Qué es el currying en programación funcional?", options:["Un tipo de recursión especial","Transformar una función de n argumentos en n funciones de 1 argumento: f(a)(b)(c) en lugar de f(a,b,c)","Una técnica de memoización","Un patrón de manejo de errores"], correct:1, explanation:"Currying permite aplicar parcialmente argumentos: const suma = a => b => a+b; const suma5 = suma(5); suma5(3)→8.", noShuffle:false },
  { concept_id:"dwec_u4_q12", unit:4, question:"¿Qué es una función pura en programación funcional?", options:["Una función que no usa parámetros","Una función que para los mismos argumentos siempre devuelve el mismo resultado y no produce efectos secundarios","Una función declarada con 'pure' keyword","Una función que solo usa tipos primitivos"], correct:1, explanation:"Funciones puras: deterministas (mismo input → mismo output) y sin side effects (no modifican estado externo). Fáciles de testear y razonar.", noShuffle:false },
  { concept_id:"dwec_u4_q13", unit:4, question:"¿Cómo se puede crear una función que recuerde el resultado de llamadas previas (memoización)?", options:["Usando var en lugar de let","Guardando resultados en una caché (objeto/Map) dentro de un closure","Duplicando la función con resultados fijos","Usando Math.memo()"], correct:1, explanation:"Memoización: const memo = {}; return function(n){ if(memo[n]) return memo[n]; return memo[n] = calcular(n); }. Mejora rendimiento para cálculos costosos.", noShuffle:false },
  { concept_id:"dwec_u4_q14", unit:4, question:"¿Qué hace Array.flatMap(fn)?", options:["Aplana el array a un nivel fijo e ignora la función","Aplica fn a cada elemento y aplana el resultado un nivel (equivalente a .map().flat(1))","Filtra y aplana simultáneamente","Convierte un array 2D a 1D sin función"], correct:1, explanation:"flatMap() es una combinación optimizada de map() seguido de flat(1). Útil cuando cada elemento puede expandirse en múltiples.", noShuffle:false },
  { concept_id:"dwec_u4_q15", unit:4, question:"¿Cuándo se ejecuta una función IIFE (Immediately Invoked Function Expression)?", options:["Al importarla con import","Inmediatamente tras su definición, sin necesidad de ser llamada explícitamente","Al hacer clic en un botón","Al cargar la página siempre, no se puede evitar"], correct:1, explanation:"IIFE: (function(){ ... })() o (() => { ... })(). Se usa para crear un scope privado. En ES6 los modules cumplen este rol.", noShuffle:false },
  { concept_id:"dwec_u4_q16", unit:4, question:"¿Cómo se comparte código entre módulos ES6?", options:["Mediante variables globales en window","Con export para exportar y import para importar","Con require() y module.exports","Con la etiqueta <share> en HTML"], correct:1, explanation:"ES6 Modules: export const fn = ()=>{} (named) o export default fn (default). import { fn } from './modulo.js' o import fn from './modulo.js'.", noShuffle:false },
  { concept_id:"dwec_u4_q17", unit:4, question:"¿Qué es el patrón módulo en JavaScript?", options:["Usar ficheros .js separados para cada función","Usar closures para crear ámbitos privados y exponer solo una API pública","Un design pattern de POO","Un tipo especial de import en Node.js"], correct:1, explanation:"El patrón módulo (pre-ES6) usa IIFE para encapsular: const modulo = (()=>{ let privado=0; return { publico:()=>privado++ }; })();", noShuffle:false },
  { concept_id:"dwec_u4_q18", unit:4, question:"¿Qué hace la función Object.create(proto)?", options:["Crea una copia exacta del objeto proto","Crea un nuevo objeto cuyo prototipo es el objeto proto especificado","Valida si proto es un objeto válido","Fusiona dos objetos"], correct:1, explanation:"Object.create() es la forma directa de establecer el prototipo. Object.create(null) crea un objeto sin prototipo (sin métodos heredados).", noShuffle:false },
  { concept_id:"dwec_u4_q19", unit:4, question:"¿Qué es el 'this' en el contexto de un método de clase?", options:["La función que contiene el método","Una referencia al objeto sobre el que se llamó el método","El valor undefined siempre","El objeto global window"], correct:1, explanation:"En un método de clase o función regular, this se refiere al objeto receptor (el que está antes del punto). En arrow functions, this es el del contexto léxico.", noShuffle:false },
  { concept_id:"dwec_u4_q20", unit:4, question:"¿Para qué sirve Function.bind(contexto, ...args)?", options:["Para ligar dos funciones en serie","Crea una nueva función con 'this' fijado al contexto dado y argumentos parciales opcionales","Para ejecutar la función en el servidor","Para deshabilitar la función temporalmente"], correct:1, explanation:"bind() devuelve una nueva función con this fijado. Útil para callbacks de eventos donde this se perdería: btn.addEventListener('click', this.handler.bind(this)).", noShuffle:false },
  { concept_id:"dwec_u4_q21", unit:4, question:"¿Cuál es la diferencia entre call() y apply() en JavaScript?", options:["call() es más moderno que apply()","Ambas invocan una función con un this especificado; call() pasa args individualmente, apply() los pasa en un array","call() solo funciona en funciones nombradas","apply() es equivalente a bind() pero lo ejecuta inmediatamente"], correct:1, explanation:"fn.call(ctx, a, b) — fn.apply(ctx, [a, b]). Ambas ejecutan fn inmediatamente con this=ctx. bind() devuelve una nueva función sin ejecutar.", noShuffle:false },
  { concept_id:"dwec_u4_q22", unit:4, question:"¿Qué es la recursividad en programación?", options:["Un bucle que se repite un número fijo de veces","Una función que se llama a sí misma hasta alcanzar un caso base","Un tipo especial de iteración con índices","Una función que llama a otra función siempre"], correct:1, explanation:"La recursión debe tener siempre un caso base que detenga las llamadas. Sin él → stack overflow (llamadas infinitas).", noShuffle:false },
  { concept_id:"dwec_u4_q23", unit:4, question:"¿Qué es la memoización aplicada a la función de Fibonacci?", options:["Guardar los resultados de cada F(n) ya calculado para no recalcularlo en llamadas futuras","Calcular todos los números de Fibonacci al inicio","Usar un bucle iterativo en lugar de recursión","Reducir el número de argumentos de la función"], correct:0, explanation:"Sin memoización, fib(40) hace millones de llamadas redundantes. Con caché/memo, cada valor se calcula una sola vez → O(n).", noShuffle:false },
  { concept_id:"dwec_u4_q24", unit:4, question:"¿Cómo se definen propiedades getter en una clase JS?", options:["function get nombre(){}","get nombre() { return this._nombre; }","property get nombre(){}","nombre.get = function(){}"], correct:1, explanation:"Los getters se definen con la palabra clave get. Se acceden como propiedades (sin ()): objeto.nombre, no objeto.nombre().", noShuffle:false },
  { concept_id:"dwec_u4_q25", unit:4, question:"¿Qué diferencia hay entre una función declarada (declaration) y una expresión de función (expression)?", options:["Son idénticas en comportamiento","Las declaraciones se hoistean completas; las expresiones solo hoistean la variable (var) pero no la función","Las expresiones no pueden tener nombre","Las declaraciones no pueden usarse como callbacks"], correct:1, explanation:"function fn(){} (declaration): hoisteable, usable antes de declararse. const fn = function(){}  (expression): la variable var es hoisted pero no su valor.", noShuffle:false },
  { concept_id:"dwec_u4_q26", unit:4, question:"¿Qué hace el método Array.forEach()?", options:["Devuelve un nuevo array transformado","Ejecuta una función para cada elemento pero NO devuelve nada (undefined)","Es igual que map()","Filtra los elementos falsy"], correct:1, explanation:"forEach() tiene efectos secundarios (como console.log) pero no retorna nada. Para transformar datos, usar map(). No se puede interrumpir con break.", noShuffle:false },
  { concept_id:"dwec_u4_q27", unit:4, question:"¿Cómo se puede implementar un módulo singleton en JavaScript?", options:["Con una variable global accesible desde cualquier parte","Con un objeto literal o una clase con constructor que compruebe si ya existe la instancia","No es posible en JavaScript","Usando localStorage"], correct:1, explanation:"Singleton con objeto literal: const singleton = { estado: 0, metodo(){} }. O con clase: if(!Cls.instancia) Cls.instancia = new Cls();", noShuffle:false },
  { concept_id:"dwec_u4_q28", unit:4, question:"¿Qué es la programación declarativa en contraposición a la imperativa?", options:["Declarar variables antes de usarlas","Describir QUÉ hacer sin especificar CÓMO (vs imperativa que describe paso a paso)","Un paradigma exclusivo de Java","Una forma de comentar el código"], correct:1, explanation:"SQL, HTML, y el uso de map/filter/reduce son estilos declarativos. Los bucles for con índices son imperativos. React JSX es declarativo.", noShuffle:false },
  { concept_id:"dwec_u4_q29", unit:4, question:"¿Qué devuelve una función JS sin la instrucción return?", options:["0","null","undefined","Error"], correct:2, explanation:"Una función sin return (o con return sin valor) devuelve undefined. Solo los constructores (new) devuelven el objeto creado implícitamente.", noShuffle:false },
  { concept_id:"dwec_u4_q30", unit:4, question:"¿Cómo se puede limitar el ámbito de una variable a un bloque específico?", options:["Usando var dentro del bloque","Usando let o const dentro del bloque","No es posible en JavaScript","Usando function() en el bloque"], correct:1, explanation:"let y const son block-scoped. var es function-scoped y 'escapa' de los bloques if/for/while. Por eso let y const son preferibles.", noShuffle:false },
  { concept_id:"dwec_u4_q31", unit:4, question:"¿Qué hace Symbol() en JavaScript?", options:["Crea un símbolo matemático","Crea un valor primitivo único e inmutable, útil como clave de propiedad que nunca colisiona","Define una constante global","Es una forma alternativa de declarar strings"], correct:1, explanation:"Symbol('desc') crea un identificador único. Dos Symbol('mismo') NO son iguales. Útil para claves de objeto privadas o bien-known symbols.", noShuffle:false },
  { concept_id:"dwec_u4_q32", unit:4, question:"¿Qué hace el método Function.prototype.toString()?", options:["Convierte el retorno de la función a string","Devuelve el código fuente de la función como string","Convierte el contexto this a string","Lanza un error de tipo"], correct:1, explanation:"fn.toString() devuelve el código fuente de la función. Útil para depuración o metaprogramación.", noShuffle:false },
  { concept_id:"dwec_u4_q33", unit:4, question:"¿Cuáles son los pilares de la Programación Orientada a Objetos (POO) en JS?", options:["Variables, funciones, objetos y arrays","Encapsulación, herencia, polimorfismo y abstracción","Clases, módulos, promises y async/await","Closures, hoisting, prototype y scope"], correct:1, explanation:"Los 4 pilares de POO: Encapsulación (datos privados), Herencia (extends), Polimorfismo (mismo método, distinto comportamiento) y Abstracción.", noShuffle:false },
  { concept_id:"dwec_u4_q34", unit:4, question:"¿Cómo se define un método estático en una clase JS?", options:["function static metodo(){}","static metodo() {} dentro de la clase","metodo.static = true","class.metodo = function(){}"], correct:1, explanation:"Los métodos static pertenecen a la clase, no a las instancias. Se llaman con Clase.metodo(), no con objeto.metodo().", noShuffle:false },
  { concept_id:"dwec_u4_q35", unit:4, question:"¿Qué hace la palabra clave 'super' en una clase hija?", options:["Accede a una propiedad súper-global","Llama al constructor o métodos de la clase padre","Convierte la clase en una superclase","Es una variable reservada para el contexto this"], correct:1, explanation:"super() en el constructor llama al constructor padre. super.metodo() llama al método del padre. Obligatorio en el constructor de la clase hija antes de usar this.", noShuffle:false },
  { concept_id:"dwec_u4_q36", unit:4, question:"¿Qué son las propiedades privadas de clase (#) en JavaScript moderno?", options:["Propiedades con el prefijo _ por convención","Propiedades verdaderamente privadas declaradas con # que solo son accesibles dentro de la clase","Variables globales restringidas","Propiedades de solo lectura definidas con Object.freeze"], correct:1, explanation:"#propiedad es una característica de clase privada real (ES2022). No accesible fuera de la clase. Diferente a _propiedad que es solo una convención.", noShuffle:false },
  { concept_id:"dwec_u4_q37", unit:4, question:"¿Qué es el patrón Observer en JavaScript?", options:["Un patrón donde un objeto observa el rendimiento de la app","Un patrón donde un sujeto notifica a múltiples observadores sobre cambios de estado","Una forma de debuggear objetos","Un patrón de gestión de errores"], correct:1, explanation:"El Observer (pub/sub) es la base de los sistemas de eventos. addEventListener es una implementación: el elemento es el sujeto, los listeners son observadores.", noShuffle:false },
  { concept_id:"dwec_u4_q38", unit:4, question:"¿Cuándo es útil usar una IIFE en JavaScript moderno?", options:["Siempre, es la mejor práctica","Para inicializar código sin contaminar el scope global, aunque los módulos ES6 han reducido su necesidad","Nunca, está deprecated","Solo para funciones de más de 100 líneas"], correct:1, explanation:"Con ES6 modules, cada fichero tiene su propio scope y las IIFEs son menos necesarias. Pero aún se usan para configuración inicial inline.", noShuffle:false },
  { concept_id:"dwec_u4_q39", unit:4, question:"¿Qué hace el operador de encadenamiento de métodos (method chaining)?", options:["Crea cadenas de texto con métodos","Permite llamar múltiples métodos en secuencia sobre el mismo objeto devolviendo this en cada uno","Encadena funciones en un array","Conecta dos objetos mediante un prototipo"], correct:1, explanation:"Method chaining: array.filter(fn).map(fn).reduce(fn). Funciona porque cada método devuelve un array nuevo. jQuery popularizó este patrón.", noShuffle:false },
  { concept_id:"dwec_u4_q40", unit:4, question:"¿Qué es el patrón Factory en JavaScript?", options:["Una función que crea y retorna objetos sin usar new, permitiendo elegir el tipo de objeto a crear según parámetros","Una forma de importar módulos dinámicamente","Un patrón para gestionar el estado global","Una técnica de optimización de memoria"], correct:0, explanation:"Factory: function crearAnimal(tipo){ if(tipo==='perro') return {ladrar:()=>'guau'}; ... }. Desacopla la creación del uso.", noShuffle:false },
  { concept_id:"dwec_u4_q41", unit:4, question:"¿Qué diferencia hay entre una función generadora (function*) y una función normal?", options:["Las funciones generadoras son más rápidas","Una función generadora puede pausar su ejecución con yield y reanudarla con .next(), siendo lazy","Las generadoras no pueden tener return","Las generadoras solo devuelven números"], correct:1, explanation:"function* genera un iterador. yield pausa y devuelve un valor. .next() reanuda. Útil para secuencias infinitas, iteración lazy.", noShuffle:false },
  { concept_id:"dwec_u4_q42", unit:4, question:"¿Para qué sirve el operador de desestructuración con valores por defecto?", options:["Para establecer el tipo de variable","Para que si una propiedad no existe en el objeto, la variable tome un valor predefinido: const {x=0, y=0} = punto","Para inicializar objetos vacíos","Para comparar objetos con valores esperados"], correct:1, explanation:"const {nombre='Anónimo', edad=18} = usuario. Si nombre o edad no existen en usuario, usarán los valores por defecto.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 5 — Eventos y formularios
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dwec_u5_q1", unit:5, question:"¿Cómo se añade un listener de eventos en JavaScript moderno?", options:["elemento.onclick = fn","elemento.addEventListener('click', fn)","elemento.on('click', fn)","<button onClick='fn()'>"], correct:1, explanation:"addEventListener permite múltiples listeners por evento, mientras que .onclick solo permite uno (el último sobreescribe al anterior).", noShuffle:false },
  { concept_id:"dwec_u5_q2", unit:5, question:"¿Qué es el 'event bubbling'?", options:["Un evento que se dispara al cargar la página","Un evento se propaga desde el elemento origen hacia sus ancestros en el DOM","Un evento que se cancela antes de llegar al objetivo","Cuando múltiples eventos se disparan simultáneamente"], correct:1, explanation:"El bubbling hace que el evento 'suba' del elemento donde ocurrió hacia sus padres hasta el documento. Se puede detener con stopPropagation().", noShuffle:false },
  { concept_id:"dwec_u5_q3", unit:5, question:"¿Para qué sirve event.preventDefault()?", options:["Eliminar el elemento al hacer clic","Cancelar el comportamiento predeterminado del navegador para ese evento","Detener la propagación a los padres","Redirigir el evento a otro elemento"], correct:1, explanation:"preventDefault() evita la acción por defecto: submit de formulario, navegación de enlace, etc. No detiene la propagación.", noShuffle:false },
  { concept_id:"dwec_u5_q4", unit:5, question:"¿Cómo se accede al valor de un input de texto desde JavaScript?", options:["document.getElementById('id').text","document.getElementById('id').value","document.getElementById('id').content","document.getElementById('id').innerHTML"], correct:1, explanation:".value es la propiedad de todos los controles de formulario (input, select, textarea). .innerHTML es para elementos de contenido.", noShuffle:false },
  { concept_id:"dwec_u5_q5", unit:5, question:"¿Qué método de formulario comprueba si todos sus campos son válidos (HTML5)?", options:["form.validate()","form.checkValidity()","form.isValid()","form.verify()"], correct:1, explanation:"checkValidity() retorna true/false. reportValidity() además muestra los mensajes de error nativos del navegador.", noShuffle:false },
  { concept_id:"dwec_u5_q6", unit:5, question:"¿Cuál es la sintaxis correcta de una expresión regular en JavaScript?", options:["regex('patrón','flags')","/ patrón /flags","RegularExpression('patrón')","'patrón'.toRegex()"], correct:1, explanation:"Literal: /patrón/flags (ej: /\\d{5}/g). O con constructor: new RegExp('\\\\d{5}', 'g').", noShuffle:false },
  { concept_id:"dwec_u5_q7", unit:5, question:"¿Qué evento se dispara cuando el usuario termina de escribir en un input y cambia el foco?", options:["input","keyup","change","blur"], correct:2, explanation:"change: valor modificado y foco perdido. input: en cada tecla. blur: al perder el foco (sin importar si cambió). focus: al ganar foco.", noShuffle:false },
  { concept_id:"dwec_u5_q8", unit:5, question:"¿Cuál es la diferencia entre event.target y event.currentTarget?", options:["Son idénticos","target es el elemento que disparó el evento; currentTarget es el elemento que tiene el listener","currentTarget es el objetivo original; target el que está procesando","Solo existe target, currentTarget no existe"], correct:1, explanation:"target: elemento original donde ocurrió el evento. currentTarget: elemento al que se adjuntó el listener (útil en delegación de eventos).", noShuffle:false },
  { concept_id:"dwec_u5_q9", unit:5, question:"¿Cómo se elimina un listener de eventos?", options:["elemento.removeListener('click', fn)","elemento.removeEventListener('click', fn)","elemento.off('click', fn)","No se pueden eliminar listeners"], correct:1, explanation:"removeEventListener() requiere la misma referencia de función que se usó en addEventListener. Las funciones anónimas inline no se pueden eliminar.", noShuffle:false },
  { concept_id:"dwec_u5_q10", unit:5, question:"¿Qué significa la fase de 'capturing' en el modelo de eventos?", options:["El evento se captura cuando el mouse hace clic","El evento desciende desde el documento hasta el elemento objetivo antes del bubbling","El evento es capturado por el servidor","Una optimización del navegador para eventos frecuentes"], correct:1, explanation:"Fase de capturing (o capture): el evento baja de document → body → ... → target. Para usarla: addEventListener('click', fn, true).", noShuffle:false },
  { concept_id:"dwec_u5_q11", unit:5, question:"¿Qué hace event.stopPropagation()?", options:["Previene el comportamiento por defecto del evento","Detiene la propagación del evento (no sube/baja más por el DOM)","Elimina el listener del evento","Cancela el evento completamente para todos los elementos"], correct:1, explanation:"stopPropagation() previene que el evento siga propagándose (bubbling o capturing). stopImmediatePropagation() además previene otros listeners en el mismo elemento.", noShuffle:false },
  { concept_id:"dwec_u5_q12", unit:5, question:"¿Qué tipos de input de HTML5 ofrecen validación nativa?", options:["Solo text y password","email, number, url, tel, date, range, color y más","Solo los que tienen atributo 'required'","Todos los inputs tienen el mismo nivel de validación"], correct:1, explanation:"HTML5 añadió muchos tipos con validación incorporada: email (formato), number (min/max), url (URL válida), required, pattern, minlength, maxlength...", noShuffle:false },
  { concept_id:"dwec_u5_q13", unit:5, question:"¿Cómo se accede al elemento seleccionado de un <select>?", options:["select.selected","select.value (valor) o select.selectedOptions (elementos seleccionados)","select.option.value","select.chosen"], correct:1, explanation:"select.value devuelve el value del option seleccionado. select.selectedIndex el índice. select.selectedOptions una HTMLCollection.", noShuffle:false },
  { concept_id:"dwec_u5_q14", unit:5, question:"¿Qué regex valida un email de forma básica?", options:["/^\\w+$/","/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/","/^email$/","/[a-z]+/"], correct:1, explanation:"La validación de email con regex es compleja. Una regex básica: /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/. En producción, mejor delegar en HTML5 type='email'.", noShuffle:false },
  { concept_id:"dwec_u5_q15", unit:5, question:"¿Qué evento se dispara cuando se hace submit a un formulario?", options:["click en el botón submit","submit en el formulario","change en el formulario","input en el formulario"], correct:1, explanation:"El evento 'submit' se dispara en el <form>. Se puede prevenir con preventDefault() para validar antes de enviar.", noShuffle:false },
  { concept_id:"dwec_u5_q16", unit:5, question:"¿Para qué sirven las cookies en JavaScript del lado cliente?", options:["Solo para rastrear usuarios","Almacenar pequeños datos en el navegador (nombre=valor) que se envían al servidor en cada petición HTTP","Para autenticar usuarios en el servidor","Para guardar imágenes en caché"], correct:1, explanation:"document.cookie permite leer y escribir cookies. Son strings limitados (~4KB). Se pueden configurar con expires, path, secure, httpOnly (solo servidor).", noShuffle:false },
  { concept_id:"dwec_u5_q17", unit:5, question:"¿Qué hace new FormData(formulario)?", options:["Crea un JSON con los datos del formulario","Crea un objeto FormData con todos los campos del formulario, incluyendo archivos","Valida todos los campos del formulario","Resetea el formulario a sus valores iniciales"], correct:1, explanation:"FormData facilita el envío de formularios con fetch() o XMLHttpRequest, incluyendo archivos multipart. formData.get('campo'), formData.append().", noShuffle:false },
  { concept_id:"dwec_u5_q18", unit:5, question:"¿Cuál es la diferencia entre los eventos keydown, keypress y keyup?", options:["Son idénticos en todos los navegadores","keydown: al presionar; keypress: mientras se mantiene (deprecated); keyup: al soltar la tecla","keypress es el más moderno","keydown solo funciona en inputs de texto"], correct:1, explanation:"Orden: keydown → keypress (deprecated, no para teclas especiales) → keyup. Para detectar teclas: keydown/keyup con event.key o event.code.", noShuffle:false },
  { concept_id:"dwec_u5_q19", unit:5, question:"¿Cómo se puede debounce un evento de input para no disparar la función en cada tecla?", options:["Usando el atributo debounce en el input","Con setTimeout: si el usuario sigue escribiendo, se cancela el timer anterior y se crea uno nuevo","Limitando el número de caracteres del input","Con event.preventDefault() en cada keyup"], correct:1, explanation:"Debounce: let timer; input.addEventListener('input', e=>{ clearTimeout(timer); timer=setTimeout(()=>buscar(e.target.value), 500); });", noShuffle:false },
  { concept_id:"dwec_u5_q20", unit:5, question:"¿Qué es la delegación de eventos y por qué es eficiente?", options:["Delegar eventos al servidor para procesarlos","Poner un único listener en el elemento padre para gestionar eventos de todos sus hijos mediante bubbling","Distribuir eventos entre varios listeners","Cachear los listeners de eventos"] , correct:1, explanation:"Con delegación, en vez de N listeners (uno por hijo), pones 1 en el padre. Eficiente para listas dinámicas. Se usa event.target para identificar el elemento.", noShuffle:false },
  { concept_id:"dwec_u5_q21", unit:5, question:"¿Qué propiedad del event te da la tecla pulsada en un evento de teclado?", options:["event.keyCode (deprecated)","event.key (la clave como string: 'Enter', 'a', 'ArrowUp'...)","event.which (deprecated)","event.charCode (deprecated)"], correct:1, explanation:"event.key es la forma moderna y recomendada. event.code da el código físico de la tecla (ej: 'KeyA' para la tecla A independientemente del idioma).", noShuffle:false },
  { concept_id:"dwec_u5_q22", unit:5, question:"¿Cuándo se dispara el evento DOMContentLoaded?", options:["Cuando todas las imágenes y estilos están cargados","Cuando el HTML está completamente parseado y el DOM construido, antes de que carguen recursos externos","Solo cuando hay errores en el DOM","Cuando el usuario interactúa por primera vez con la página"], correct:1, explanation:"DOMContentLoaded: DOM listo pero CSS/imágenes quizás no. load: todo cargado. DOMContentLoaded es preferible para scripts que manipulan el DOM.", noShuffle:false },
  { concept_id:"dwec_u5_q23", unit:5, question:"¿Cómo se accede a los checkboxes marcados de un formulario?", options:["form.checkedBoxes","document.querySelectorAll('input[type=checkbox]:checked')","form.elements.checked","document.checkboxes.selected"], correct:1, explanation:"querySelectorAll con el pseudo-selector :checked selecciona todos los checkboxes (o radios, options) que están marcados.", noShuffle:false },
  { concept_id:"dwec_u5_q24", unit:5, question:"¿Para qué sirve el atributo 'data-*' en HTML y cómo se accede desde JS?", options:["Para definir el tipo de datos del elemento","Para añadir datos personalizados accesibles con element.dataset.nombreAtributo","Para almacenar CSS en el HTML","Para vincular el elemento a una base de datos"], correct:1, explanation:"data-usuario-id='42' → element.dataset.usuarioId (camelCase automático). Útil para guardar datos en el DOM sin JS global.", noShuffle:false },
  { concept_id:"dwec_u5_q25", unit:5, question:"¿Qué hace document.cookie = 'nombre=valor'?", options:["Reemplaza TODAS las cookies con solo esa","AÑADE (o actualiza) esa cookie sin afectar las demás","Elimina todas las cookies excepto esa","Lanza un error si ya existe una cookie con ese nombre"], correct:1, explanation:"Asignar a document.cookie no reemplaza, AÑADE. Para eliminar: establecer expires en el pasado. Para leer: parsear el string de document.cookie.", noShuffle:false },
  { concept_id:"dwec_u5_q26", unit:5, question:"¿Qué evento se dispara cuando un elemento gana el foco (ej: usuario hace clic en un input)?", options:["click","focus","activate","select"], correct:1, explanation:"focus: el elemento gana el foco. blur: lo pierde. focusin/focusout: como focus/blur pero se propagan (bubbling). Útil para validación al entrar/salir de un campo.", noShuffle:false },
  { concept_id:"dwec_u5_q27", unit:5, question:"¿Cómo se detecta si el usuario está online u offline en JavaScript?", options:["navigator.checkConnection()","navigator.onLine (boolean) y los eventos 'online'/'offline' en window","window.network.status","fetch('test.txt').then(online => true)"], correct:1, explanation:"navigator.onLine y window.addEventListener('online/offline', fn) permiten detectar conectividad. No siempre es 100% fiable para determinar conectividad real.", noShuffle:false },
  { concept_id:"dwec_u5_q28", unit:5, question:"¿Qué hace el atributo HTML 'pattern' en un input?", options:["Aplica un patrón CSS al input","Especifica una regex que el valor del input debe cumplir para ser válido","Define el patrón de colores del input","Establece el formato de fecha del input"], correct:1, explanation:"pattern='[A-Za-z]{3}' valida que solo contenga 3 letras. Se combina con title para dar un mensaje de error personalizado.", noShuffle:false },
  { concept_id:"dwec_u5_q29", unit:5, question:"¿Qué es el throttle de eventos y en qué se diferencia del debounce?", options:["Son sinónimos","Throttle: ejecuta la función como máximo cada N ms; Debounce: espera N ms desde la última llamada antes de ejecutar","Throttle solo funciona con eventos de teclado; Debounce con ratón","Throttle para llamadas async; Debounce para síncronas"], correct:1, explanation:"Throttle (para scroll/resize): ejecuta cada 100ms máximo. Debounce (para búsqueda): ejecuta 500ms después del último evento. Ambos optimizan el rendimiento.", noShuffle:false },
  { concept_id:"dwec_u5_q30", unit:5, question:"¿Qué hace element.dispatchEvent(new Event('click'))?", options:["Simula un clic real del usuario","Dispara el evento 'click' programáticamente en el elemento, ejecutando sus listeners","Redirige el clic al servidor","Elimina todos los listeners de click del elemento"], correct:1, explanation:"dispatchEvent() permite disparar eventos custom o nativos programáticamente. Útil para testing o para comunicación entre componentes.", noShuffle:false },
  { concept_id:"dwec_u5_q31", unit:5, question:"¿Cómo se crea y se dispara un CustomEvent en JavaScript?", options:["new Event('miEvento', {detail: datos}) y elemento.dispatchEvent(ev)","new CustomEvent('miEvento', {detail: datos}) y elemento.dispatchEvent(ev)","EventEmitter.emit('miEvento', datos)","element.trigger('miEvento', datos)"], correct:1, explanation:"CustomEvent permite pasar datos extra con detail: const ev = new CustomEvent('producto:añadido', {detail:{id:1}}); document.dispatchEvent(ev);", noShuffle:false },
  { concept_id:"dwec_u5_q32", unit:5, question:"¿Qué devuelve la regex /\\d+/.test('abc123')?", options:["false","true","'123'","null"], correct:1, explanation:"test() devuelve true si hay alguna coincidencia. '\\d+' busca uno o más dígitos. 'abc123' contiene '123', así que test() → true.", noShuffle:false },
  { concept_id:"dwec_u5_q33", unit:5, question:"¿Cuándo se ejecuta el evento 'load' en window?", options:["Cuando el DOM está listo","Cuando TODOS los recursos han cargado (HTML, CSS, imágenes, scripts)","Cuando el usuario hace scroll hasta el final","Cuando la página termina de renderizarse visualmente"], correct:1, explanation:"window.addEventListener('load', fn) espera a que todo esté cargado. Más lento que DOMContentLoaded. Usa DOMContentLoaded cuando solo necesitas el DOM.", noShuffle:false },
  { concept_id:"dwec_u5_q34", unit:5, question:"¿Para qué sirve el evento 'input' en un elemento de formulario?", options:["Se dispara al hacer submit","Se dispara INMEDIATAMENTE en cada cambio del valor, incluyendo pegar, borrar y dictar","Se dispara cuando el campo pierde el foco","Se dispara solo con el teclado, no con ratón"], correct:1, explanation:"'input' se dispara en tiempo real con cada cambio. Ideal para búsqueda en tiempo real o contadores de caracteres. 'change' solo al confirmar.", noShuffle:false },
  { concept_id:"dwec_u5_q35", unit:5, question:"¿Qué propiedad del objeto event da las coordenadas del ratón relativas al viewport?", options:["event.x y event.y","event.clientX y event.clientY","event.pageX y event.pageY","event.offsetX y event.offsetY"], correct:1, explanation:"clientX/Y: relativo al viewport. pageX/Y: relativo al documento (incluye scroll). offsetX/Y: relativo al elemento. screenX/Y: relativo a la pantalla.", noShuffle:false },
  { concept_id:"dwec_u5_q36", unit:5, question:"¿Qué hace element.form en un input de formulario?", options:["Envía el formulario del elemento","Devuelve una referencia al elemento <form> al que pertenece el input","Establece el formulario padre del input","Valida el formulario del input"], correct:1, explanation:"element.form devuelve el formulario contenedor. Permite acceder al formulario desde cualquier control hijo sin usar querySelector.", noShuffle:false },
  { concept_id:"dwec_u5_q37", unit:5, question:"¿Cómo se puede prevenir que el usuario envíe un formulario vacío?", options:["Añadiendo 'required' en HTML o validando en el listener 'submit' con preventDefault()","Usando CSS pointer-events: none en el botón","No es posible con JavaScript","Deshabilitando el botón con JavaScript siempre"], correct:0, explanation:"Doble validación: atributo required en HTML para UX inmediata, Y validación JS en el submit para lógica más compleja.", noShuffle:false },
  { concept_id:"dwec_u5_q38", unit:5, question:"¿Qué hace la propiedad element.validity en los formularios HTML5?", options:["Activa la validación CSS del elemento","Devuelve un ValidityState con flags indicando qué restricción falla (valueMissing, patternMismatch, rangeOverflow...)","Valida el elemento y muestra un alert","Comprueba la validez del nombre del campo"], correct:1, explanation:"ValidityState tiene propiedades booleanas: valid, valueMissing (required), typeMismatch (email/url), patternMismatch, rangeOverflow/Underflow, tooLong/Short.", noShuffle:false },
  { concept_id:"dwec_u5_q39", unit:5, question:"¿Cómo se puede leer el valor de un grupo de radio buttons?", options:["document.querySelector('[type=radio]:checked')","document.querySelector('input[name=miGrupo]:checked').value","radioGroup.value","document.getRadioValue('miGrupo')"], correct:1, explanation:"querySelector('input[name=grupo]:checked') selecciona el radio button marcado del grupo. Si ninguno está marcado, devuelve null.", noShuffle:false },
  { concept_id:"dwec_u5_q40", unit:5, question:"¿Qué evento se dispara al redimensionar la ventana del navegador?", options:["resize en window","scroll en window","change en window","viewport en window"], correct:0, explanation:"window.addEventListener('resize', fn). Se recomienda usar throttle/debounce ya que puede dispararse cientos de veces durante el redimensionado.", noShuffle:false },
  { concept_id:"dwec_u5_q41", unit:5, question:"¿Qué es el atributo 'autocomplete' en un formulario HTML?", options:["Añade autocompletado personalizado con JS","Indica al navegador si debe ofrecer sugerencias basadas en entradas previas del usuario","Define una función de JS para autocompletar","Conecta el campo con una API de sugerencias"], correct:1, explanation:"autocomplete='on/off' o valores específicos ('email', 'username', 'current-password'...) controlan el autocompletado del navegador y los gestores de contraseñas.", noShuffle:false },
  { concept_id:"dwec_u5_q42", unit:5, question:"¿Qué hace element.setCustomValidity('mensaje')?", options:["Establece un mensaje de error CSS personalizado","Marca el elemento como inválido con un mensaje personalizado que se muestra con reportValidity()","Valida el campo contra un schema JSON","Cambia el placeholder del campo"], correct:1, explanation:"setCustomValidity('') = válido. setCustomValidity('Error') = inválido. Permite integrar validación custom con el sistema nativo de HTML5.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 6 — DOM (Document Object Model)
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dwec_u6_q1", unit:6, question:"¿Qué es el DOM en el contexto web?", options:["Un lenguaje alternativo a JavaScript","Una representación en árbol del documento HTML que el navegador expone a JavaScript","Un protocolo de comunicación cliente-servidor","Un framework de JavaScript"], correct:1, explanation:"El DOM permite a JS leer y modificar el contenido, estructura y estilos de una página web de forma dinámica.", noShuffle:false },
  { concept_id:"dwec_u6_q2", unit:6, question:"¿Qué método selecciona el PRIMER elemento que coincida con un selector CSS?", options:["document.getElementById()","document.getElementsByClassName()","document.querySelector()","document.querySelectorAll()"], correct:2, explanation:"querySelector() devuelve el primer elemento. querySelectorAll() devuelve una NodeList con todos los coincidentes.", noShuffle:false },
  { concept_id:"dwec_u6_q3", unit:6, question:"¿Cómo se crea y añade un nuevo elemento HTML al DOM?", options:["document.addElement('div') y parent.insert(el)","document.createElement('div') y parent.appendChild(el)","new HTMLElement('div') y DOM.add(el)","document.make('div') y body.push(el)"], correct:1, explanation:"1) createElement() 2) configurar propiedades 3) appendChild() o prepend() o insertBefore() para insertarlo.", noShuffle:false },
  { concept_id:"dwec_u6_q4", unit:6, question:"¿Cuál es la diferencia entre innerHTML y textContent?", options:["innerHTML solo funciona en <div>","innerHTML interpreta etiquetas HTML; textContent trata el contenido como texto plano (más seguro y rápido)","textContent es más lento","No hay diferencia"], correct:1, explanation:"innerHTML parsea HTML (riesgo XSS si es entrada del usuario). textContent solo texto plano. innerText considera el CSS aplicado (texto visible).", noShuffle:false },
  { concept_id:"dwec_u6_q5", unit:6, question:"¿Cómo se agrega una clase CSS a un elemento desde JavaScript?", options:["elemento.class += 'nueva'","elemento.style.class = 'nueva'","elemento.classList.add('nueva')","elemento.addClassName('nueva')"], correct:2, explanation:"classList.add(), remove(), toggle(), contains(), replace(). Más seguro que manipular className directamente (que reemplaza todo).", noShuffle:false },
  { concept_id:"dwec_u6_q6", unit:6, question:"¿Qué es la delegación de eventos en el DOM?", options:["Pasar la gestión de eventos a un framework externo","Asignar un listener a un elemento padre para gestionar eventos de sus hijos mediante el bubbling","Dividir un evento en varios eventos simples","Ejecutar múltiples funciones con un solo evento"], correct:1, explanation:"La delegación es eficiente: 1 listener en el padre gestiona todos los hijos dinámicos. Se usa event.target para identificar el elemento clicado.", noShuffle:false },
  { concept_id:"dwec_u6_q7", unit:6, question:"¿Cómo se modifica el estilo CSS de un elemento directamente desde JavaScript?", options:["elemento.css.propiedad = valor","elemento.style.propiedad = valor (camelCase)","elemento.setStyle('propiedad', valor)","CSS.set(elemento, 'propiedad', valor)"], correct:1, explanation:"element.style.backgroundColor = 'red'. Las propiedades CSS se escriben en camelCase en JS (background-color → backgroundColor).", noShuffle:false },
  { concept_id:"dwec_u6_q8", unit:6, question:"¿Qué devuelve document.getElementById('id') si el elemento no existe?", options:["undefined","null","un objeto vacío","Error"], correct:1, explanation:"getElementById devuelve null si no encuentra el elemento. querySelector también. Verificar: if(el) antes de usarlo.", noShuffle:false },
  { concept_id:"dwec_u6_q9", unit:6, question:"¿Qué diferencia hay entre NodeList y HTMLCollection?", options:["Son idénticos","HTMLCollection es live (se actualiza automáticamente); NodeList puede ser live o estática según el método usado","NodeList solo contiene elementos HTML; HTMLCollection cualquier nodo","HTMLCollection es más moderno"], correct:1, explanation:"getElementsBy... devuelve HTMLCollection (live). querySelectorAll devuelve NodeList estática. querySelector devuelve Element o null.", noShuffle:false },
  { concept_id:"dwec_u6_q10", unit:6, question:"¿Cómo se elimina un elemento del DOM?", options:["delete elemento","elemento.remove() o elemento.parentNode.removeChild(elemento)","elemento.destroy()","document.remove(elemento)"], correct:1, explanation:"remove() es el método moderno. removeChild() es el clásico (requiere tener la referencia al padre). También: padre.innerHTML = '' para eliminar todos los hijos.", noShuffle:false },
  { concept_id:"dwec_u6_q11", unit:6, question:"¿Qué hace element.getAttribute('src')?", options:["Establece el valor del atributo src","Devuelve el valor actual del atributo src tal como está en el HTML","Comprueba si el elemento tiene el atributo src","Crea el atributo src si no existe"], correct:1, explanation:"getAttribute() devuelve el valor del atributo HTML. element.src devuelve la URL absoluta resuelta. Son distintos para URLs relativas.", noShuffle:false },
  { concept_id:"dwec_u6_q12", unit:6, question:"¿Cómo se accede al padre de un elemento en el DOM?", options:["elemento.parent","elemento.parentNode o elemento.parentElement","elemento.father","elemento.container"], correct:1, explanation:"parentNode: el nodo padre (puede ser Document). parentElement: el elemento padre (null si el padre no es Element).", noShuffle:false },
  { concept_id:"dwec_u6_q13", unit:6, question:"¿Qué hace element.insertAdjacentHTML('beforeend', html)?", options:["Inserta HTML antes del elemento","Inserta HTML como último hijo dentro del elemento","Inserta HTML después del elemento","Reemplaza el HTML interno del elemento"], correct:1, explanation:"insertAdjacentHTML posiciones: 'beforebegin' (antes del el), 'afterbegin' (primer hijo), 'beforeend' (último hijo), 'afterend' (después del el).", noShuffle:false },
  { concept_id:"dwec_u6_q14", unit:6, question:"¿Para qué sirve document.createDocumentFragment()?", options:["Para crear un documento HTML completo","Para crear un nodo temporal que minimiza el reflow al añadir múltiples elementos al DOM de una vez","Para documentar el código JavaScript","Para crear una copia del DOM actual"], correct:1, explanation:"DocumentFragment es un nodo liviano fuera del DOM. Se añaden hijos a él y luego se inserta el fragment entero → 1 solo reflow en lugar de N.", noShuffle:false },
  { concept_id:"dwec_u6_q15", unit:6, question:"¿Cómo se clona un elemento del DOM incluyendo todos sus hijos?", options:["elemento.copy()","elemento.cloneNode(true)","Object.assign({}, elemento)","document.clone(elemento)"], correct:1, explanation:"cloneNode(true) clona el elemento y todos sus descendientes. cloneNode(false) clona solo el elemento sin hijos. Los ids duplicados deben cambiarse.", noShuffle:false },
  { concept_id:"dwec_u6_q16", unit:6, question:"¿Qué hace classList.toggle('activo')?", options:["Añade siempre la clase 'activo'","Añade la clase si no la tiene, o la elimina si ya la tiene","Comprueba si el elemento tiene la clase","Reemplaza todas las clases por 'activo'"], correct:1, explanation:"toggle() es conveniente para botones on/off. toggle('clase', condición) añade si condición es true, elimina si es false.", noShuffle:false },
  { concept_id:"dwec_u6_q17", unit:6, question:"¿Cómo se puede obtener las dimensiones y posición de un elemento en la página?", options:["elemento.position()","elemento.getBoundingClientRect()","elemento.size","getComputedStyle(elemento).width"], correct:1, explanation:"getBoundingClientRect() devuelve {top, left, bottom, right, width, height} relativo al viewport. Para posición en el documento, se suma el scroll.", noShuffle:false },
  { concept_id:"dwec_u6_q18", unit:6, question:"¿Qué hace document.querySelector(':root')?", options:["Selecciona el nodo raíz del JavaScript","Selecciona el elemento <html> (raíz del documento)","Selecciona el elemento con id 'root'","Selecciona document.body"], correct:1, explanation:":root es el pseudo-elemento que referencia el elemento raíz (<html>). Útil para leer/modificar variables CSS: getComputedStyle(root).getPropertyValue('--color').", noShuffle:false },
  { concept_id:"dwec_u6_q19", unit:6, question:"¿Cómo se establece una variable CSS desde JavaScript?", options:["document.style.setProperty('--color', 'red')","document.documentElement.style.setProperty('--color', 'red')","CSS.setVar('--color', 'red')","root.cssVar['--color'] = 'red'"], correct:1, explanation:"document.documentElement es el <html>. style.setProperty permite cambiar variables CSS y todas las reglas que las usen se actualizan automáticamente.", noShuffle:false },
  { concept_id:"dwec_u6_q20", unit:6, question:"¿Qué es el shadow DOM?", options:["El DOM de las páginas en modo oscuro","Un DOM encapsulado, adjunto a un elemento, cuyo estilo y estructura están aislados del resto de la página","La representación del DOM en memoria antes de renderizar","El DOM de iframes incrustados"], correct:1, explanation:"Shadow DOM es la base de los Web Components. Permite encapsular HTML/CSS en un elemento custom sin que los estilos globales lo afecten.", noShuffle:false },
  { concept_id:"dwec_u6_q21", unit:6, question:"¿Para qué sirve MutationObserver?", options:["Para observar cambios en el rendimiento de la página","Para detectar y reaccionar a cambios en el DOM (añadir/eliminar nodos, cambiar atributos) de forma eficiente","Para observar cambios en el CSS","Para monitorizar peticiones de red"], correct:1, explanation:"MutationObserver es más eficiente que los eventos de mutación DOM antiguos (deprecated). Útil para widgets que reaccionan a cambios externos en el DOM.", noShuffle:false },
  { concept_id:"dwec_u6_q22", unit:6, question:"¿Qué propiedad CSS controla el orden visual de elementos flex/grid sin cambiar el DOM?", options:["z-index","order","position","display"], correct:1, explanation:"La propiedad CSS 'order' cambia el orden visual sin modificar el DOM. Útil para responsive design donde el orden cambia en móvil.", noShuffle:false },
  { concept_id:"dwec_u6_q23", unit:6, question:"¿Qué hace element.scrollIntoView()?", options:["Hace scroll hasta poner el elemento visible en el viewport","Oculta el elemento al hacer scroll","Escucha el evento de scroll del elemento","Establece la posición de scroll del elemento"], correct:0, explanation:"scrollIntoView() desplaza la página para hacer visible el elemento. scrollIntoView({behavior:'smooth', block:'center'}) para scroll suave.", noShuffle:false },
  { concept_id:"dwec_u6_q24", unit:6, question:"¿Qué hace document.createElement('template')?", options:["Crea un elemento de plantilla Handlebars","Crea un elemento <template> HTML5 cuyo contenido no se renderiza pero es clonable","Crea una plantilla de email","Crea un elemento de plantilla para CSS"], correct:1, explanation:"<template> es inerte (no renderizado, no descarga recursos). template.content es un DocumentFragment con el markup. Se usa con Web Components.", noShuffle:false },
  { concept_id:"dwec_u6_q25", unit:6, question:"¿Qué es IntersectionObserver en JavaScript?", options:["Un observer que monitoriza colisiones entre elementos DOM","Una API que detecta si un elemento entra o sale del viewport (o de un contenedor), de forma eficiente","Un observer de cambios en estilos CSS","Un listener de eventos de scroll optimizado"], correct:1, explanation:"IntersectionObserver es perfecto para lazy loading de imágenes, animaciones on-scroll y infinite scroll. Mucho más eficiente que el listener scroll+getBoundingClientRect.", noShuffle:false },
  { concept_id:"dwec_u6_q26", unit:6, question:"¿Qué hace element.closest(selector)?", options:["Devuelve el elemento más cercano en el DOM que coincide con el selector, subiendo por los ancestros","Devuelve el descendiente más cercano que coincide","Devuelve true si el elemento es próximo a otro","Selecciona elementos cercanos geográficamente"], correct:0, explanation:"closest() sube por los ancestros desde el elemento actual hasta encontrar uno que coincida con el selector (o null si no lo encuentra).", noShuffle:false },
  { concept_id:"dwec_u6_q27", unit:6, question:"¿Qué hace element.matches(selector)?", options:["Busca elementos dentro del DOM","Devuelve true si el elemento coincide con el selector CSS dado","Compara dos elementos del DOM","Selecciona el elemento que coincide con el selector"], correct:1, explanation:"matches() es útil en delegación de eventos para comprobar si el event.target es del tipo esperado: if(event.target.matches('.btn')){ ... }", noShuffle:false },
  { concept_id:"dwec_u6_q28", unit:6, question:"¿Cómo se puede acceder a todos los atributos de un elemento HTML?", options:["elemento.attributesList","elemento.attributes (NamedNodeMap iterable)","elemento.getAttributes()","Object.keys(elemento)"], correct:1, explanation:"element.attributes devuelve un NamedNodeMap. También: element.hasAttribute(), element.removeAttribute(). getAttributeNames() devuelve un array de nombres.", noShuffle:false },
  { concept_id:"dwec_u6_q29", unit:6, question:"¿Cuál es la diferencia entre element.children y element.childNodes?", options:["Son idénticos","children: solo elementos HTML hijos; childNodes: todos los nodos hijos (incluyendo texto, comentarios)","childNodes es live; children es estático","children solo existe en listas"], correct:1, explanation:"childNodes incluye nodos de texto (espacios en blanco entre elementos), comentarios, etc. children solo devuelve elementos HTML (HTMLCollection live).", noShuffle:false },
  { concept_id:"dwec_u6_q30", unit:6, question:"¿Para qué sirve requestAnimationFrame(callback)?", options:["Para ejecutar código en un nuevo hilo","Para ejecutar animaciones en el siguiente repintado del navegador, sincronizadas con la frecuencia de refresco","Para retrasar la ejecución un frame de tiempo","Para ejecutar código antes de que el DOM esté listo"], correct:1, explanation:"rAF sincroniza con el ciclo de repintado (~60fps). Más eficiente que setInterval para animaciones. El callback recibe el timestamp actual.", noShuffle:false },
  { concept_id:"dwec_u6_q31", unit:6, question:"¿Qué es el Virtual DOM y qué problema resuelve?", options:["Una copia del DOM almacenada en el servidor","Una representación JS del DOM en memoria que permite comparar cambios y actualizar el DOM real de forma mínima (React, Vue)","Una versión simplificada del DOM para aplicaciones simples","Un DOM cifrado por seguridad"], correct:1, explanation:"El Virtual DOM (React) hace diff entre el VDOM anterior y el nuevo, y solo aplica los cambios mínimos al DOM real, mejorando el rendimiento.", noShuffle:false },
  { concept_id:"dwec_u6_q32", unit:6, question:"¿Qué hace element.prepend(nodo)?", options:["Añade el nodo al final de los hijos del elemento","Añade el nodo como PRIMER hijo del elemento","Inserta el nodo antes del elemento en el DOM","Reemplaza el primer hijo del elemento"], correct:1, explanation:"prepend() añade al principio. append() al final. before() antes del elemento. after() después del elemento. Todos aceptan múltiples argumentos y strings.", noShuffle:false },
  { concept_id:"dwec_u6_q33", unit:6, question:"¿Qué propiedad permite leer el texto visible de un elemento considerando el CSS aplicado?", options:["textContent","innerHTML","innerText","nodeValue"], correct:2, explanation:"innerText devuelve el texto visible (considera display:none → no incluido). textContent devuelve todo el texto sin considerar CSS. innerHTML incluye tags HTML.", noShuffle:false },
  { concept_id:"dwec_u6_q34", unit:6, question:"¿Cómo se puede iterar sobre una NodeList?", options:["Solo con un bucle for clásico","Con forEach() directamente, for...of, o convirtiéndola en array con Array.from()","Solo con for...in","No se puede iterar, hay que acceder por índice"], correct:1, explanation:"NodeList.forEach() funciona en navegadores modernos. Array.from(nodeList) o [...nodeList] la convierte en array para usar map/filter/reduce.", noShuffle:false },
  { concept_id:"dwec_u6_q35", unit:6, question:"¿Qué hace getComputedStyle(elemento)?", options:["Computa las animaciones CSS del elemento","Devuelve los estilos CSS finales calculados (incluyendo los de hojas de estilo y herencia)","Establece el estilo calculado del elemento","Devuelve solo los estilos inline del elemento"], correct:1, explanation:"getComputedStyle(el) devuelve los valores finales CSS. Útil para leer propiedades no accesibles con element.style (que solo lee estilos inline).", noShuffle:false },
  { concept_id:"dwec_u6_q36", unit:6, question:"¿Qué hace document.createTextNode('texto')?", options:["Crea un elemento <text>","Crea un nodo de texto plano para insertar en el DOM de forma segura (sin riesgo de XSS)","Crea un elemento span con el texto","Formatea el texto con la fuente por defecto"], correct:1, explanation:"createTextNode() es la forma más segura de insertar texto dinámico en el DOM sin riesgo de inyección HTML.", noShuffle:false },
  { concept_id:"dwec_u6_q37", unit:6, question:"¿Qué devuelve element.nextElementSibling?", options:["El siguiente nodo hermano (incluyendo nodos de texto)","El siguiente elemento hermano en el DOM","El siguiente elemento en el árbol de herencia","null siempre si es el último element"], correct:1, explanation:"nextElementSibling: el siguiente hermano que sea elemento. nextSibling: el siguiente nodo (puede ser texto o comentario).", noShuffle:false },
  { concept_id:"dwec_u6_q38", unit:6, question:"¿Cómo se puede hacer scroll suave hasta el inicio de la página?", options:["window.scroll(0,0)","window.scrollTo({top:0, behavior:'smooth'})","document.body.scrollTop = 0","page.scrollToTop()"], correct:1, explanation:"scrollTo({top:0, behavior:'smooth'}) activa el scroll suave del navegador. Alternativa CSS: html { scroll-behavior: smooth; }", noShuffle:false },
  { concept_id:"dwec_u6_q39", unit:6, question:"¿Qué hace element.replaceWith(nuevoElemento)?", options:["Reemplaza el contenido interno del elemento","Reemplaza el elemento por otro en el DOM (el elemento es eliminado)","Crea una copia del elemento con nuevo contenido","Intercambia el elemento con otro elemento de la página"], correct:1, explanation:"replaceWith() reemplaza el elemento en el árbol DOM por el nuevo elemento dado. Similar al antiguo parentNode.replaceChild().", noShuffle:false },
  { concept_id:"dwec_u6_q40", unit:6, question:"¿Qué es el reflow (o layout) en el contexto del rendimiento del navegador?", options:["La recarga completa de la página","El proceso de recalcular las posiciones y tamaños de todos los elementos afectados por un cambio de layout","El proceso de repintado de píxeles en pantalla","La descarga de nuevos recursos CSS"], correct:1, explanation:"El reflow es costoso en rendimiento. Se activa al cambiar propiedades de layout (width, height, top, etc.). Minimizarlo: leer propiedades en batch, usar transform/opacity.", noShuffle:false },
  { concept_id:"dwec_u6_q41", unit:6, question:"¿Cómo se puede añadir HTML en una cadena de texto de forma segura sin riesgo de XSS?", options:["innerHTML con el string del usuario","Crear nodos con createElement/createTextNode y appendChild","DOMParser para parsear el string","document.write(string)"], correct:1, explanation:"innerHTML con datos del usuario es peligroso (XSS). La forma segura es textContent para texto, o DOMPurify para sanitizar HTML de usuario.", noShuffle:false },
  { concept_id:"dwec_u6_q42", unit:6, question:"¿Qué hace document.querySelectorAll('p:not(.excluido)')?", options:["Selecciona todos los <p> excepto el primero","Selecciona todos los <p> que NO tienen la clase 'excluido'","Selecciona todos los elementos que no son <p>","Excluye párrafos del DOM"], correct:1, explanation:":not() es un pseudo-selector CSS que excluye los elementos que coinciden con el argumento. Funciona con cualquier selector en querySelectorAll.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 7 — AJAX y comunicación asíncrona
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dwec_u7_q1", unit:7, question:"¿Qué significa AJAX?", options:["Automated JavaScript and XML","Asynchronous JavaScript and XML","Advanced Java Application Extension","Asynchronous JSON and XHTML"], correct:1, explanation:"AJAX permite actualizar partes de una página sin recargarla. Hoy se usa principalmente JSON en lugar de XML.", noShuffle:false },
  { concept_id:"dwec_u7_q2", unit:7, question:"¿Cuál es la forma moderna de hacer peticiones HTTP asíncronas en JavaScript?", options:["XMLHttpRequest()","$.ajax() de jQuery","fetch()","http.get()"], correct:2, explanation:"La Fetch API es moderna, basada en Promises y más limpia que XHR. Soporta async/await.", noShuffle:false },
  { concept_id:"dwec_u7_q3", unit:7, question:"¿Qué es una Promise en JavaScript?", options:["Un tipo especial de array","Un objeto que representa el resultado eventual de una operación asíncrona","Una garantía de que el código nunca fallará","Una librería para gestionar callbacks"], correct:1, explanation:"Promise tiene 3 estados: pending, fulfilled, rejected. Se consume con .then()/.catch() o async/await.", noShuffle:false },
  { concept_id:"dwec_u7_q4", unit:7, question:"¿Qué hace 'await' dentro de una función async?", options:["Detiene todo el navegador","Pausa la función async hasta que la Promise se resuelva, sin bloquear el hilo principal","Convierte código síncrono en asíncrono","Cancela la Promise si tarda más de 5s"], correct:1, explanation:"await pausa la función async (no el hilo principal). Permite código asíncrono con apariencia síncrona y manejo de errores con try/catch.", noShuffle:false },
  { concept_id:"dwec_u7_q5", unit:7, question:"¿Qué ventaja tiene JSON sobre XML para intercambiar datos en webs?", options:["JSON soporta más tipos de datos","JSON es más ligero, legible y se parsea nativamente con JavaScript","XML es más inseguro","JSON permite incrustar imágenes"], correct:1, explanation:"JSON es compacto, legible y nativo en JS (JSON.parse/stringify). XML es más verboso y requiere parsers especiales.", noShuffle:false },
  { concept_id:"dwec_u7_q6", unit:7, question:"¿Qué política de seguridad impide a un script acceder a recursos de otro dominio?", options:["CSP","CORS","SOP (Same-Origin Policy)","HTTPS"], correct:2, explanation:"SOP bloquea peticiones cross-origin por seguridad. CORS es el mecanismo que permite excepciones controladas (cabecera Access-Control-Allow-Origin).", noShuffle:false },
  { concept_id:"dwec_u7_q7", unit:7, question:"¿Cómo se maneja el error en una petición fetch()?", options:["fetch automáticamente lanza Error para respuestas no-200","Con .catch() o try/catch con await; también comprobando response.ok","Solo con el código de estado","fetch no puede fallar nunca"], correct:1, explanation:"fetch() solo rechaza la Promise si hay error de red. Un 404 o 500 resuelve la Promise; hay que comprobar response.ok o response.status.", noShuffle:false },
  { concept_id:"dwec_u7_q8", unit:7, question:"¿Cómo se hace una petición POST con fetch()?", options:["fetch('url', {method:'POST', body:datos})","fetch.post('url', datos)","fetch('url', 'POST', datos)","POST('url', datos)"], correct:0, explanation:"fetch(url, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(datos) })", noShuffle:false },
  { concept_id:"dwec_u7_q9", unit:7, question:"¿Qué hace Promise.all([p1, p2, p3])?", options:["Ejecuta las promises en secuencia","Espera a que TODAS las promises se resuelvan y devuelve un array con los resultados","Devuelve el resultado de la primera que resuelva","Cancela las promises si una falla"], correct:1, explanation:"Promise.all() es paralelo y falla si cualquiera rechaza. Promise.allSettled() espera a todas sin fallar. Promise.race() devuelve la primera.", noShuffle:false },
  { concept_id:"dwec_u7_q10", unit:7, question:"¿Cuáles son los estados posibles de una Promise?", options:["running, done, error","pending, fulfilled, rejected","loading, success, failed","active, resolved, cancelled"], correct:1, explanation:"pending: operación en curso. fulfilled: completada con éxito. rejected: falló. Una vez settled (resuelta o rechazada), no puede cambiar.", noShuffle:false },
  { concept_id:"dwec_u7_q11", unit:7, question:"¿Qué devuelve response.json() en una petición fetch()?", options:["El JSON como string","Una Promise que resuelve con el objeto JavaScript parseado del JSON","El JSON formateado","El objeto response completo"], correct:1, explanation:"response.json() es asíncrono. También: response.text(), response.blob() para otros tipos. Todos devuelven Promises.", noShuffle:false },
  { concept_id:"dwec_u7_q12", unit:7, question:"¿Qué es un WebSocket?", options:["Una versión mejorada de HTTP","Un protocolo de comunicación bidireccional y full-duplex entre cliente y servidor sobre una sola conexión TCP persistente","Una API para hacer peticiones HTTP más rápidas","Un tipo de cookie de sesión"], correct:1, explanation:"WebSockets permiten comunicación en tiempo real: chat, gaming, cotizaciones en vivo. A diferencia de HTTP, el servidor puede enviar datos sin petición del cliente.", noShuffle:false },
  { concept_id:"dwec_u7_q13", unit:7, question:"¿Cómo se crea una Promise personalizada?", options:["new Promise((resolver)=>{ resolver(valor); })","Promise.create((resolve,reject)=>{})","new Promise((resolve, reject)=>{ ... resolve(valor) o reject(error) })","Promise((resolve)=>resolve(valor))"], correct:2, explanation:"new Promise((resolve, reject)=>{ try{ resolve(resultado); } catch(e){ reject(e); } })", noShuffle:false },
  { concept_id:"dwec_u7_q14", unit:7, question:"¿Qué diferencia hay entre Promise.race() y Promise.any()?", options:["Son equivalentes","race() devuelve la primera que se establece (resuelta O rechazada); any() devuelve la primera resuelta (ignora rechazos)","race() es más moderno que any()","any() solo funciona con 2 promises"], correct:1, explanation:"race() → primera (sea fulfillment o rejection). any() → primera fulfillment (falla solo si TODAS rechazan, con AggregateError). ES2021.", noShuffle:false },
  { concept_id:"dwec_u7_q15", unit:7, question:"¿Qué cabecera HTTP especifica el tipo de contenido enviado en el body de una petición POST?", options:["Content-Type","Accept","Authorization","X-Custom-Header"], correct:0, explanation:"Content-Type: application/json para JSON, application/x-www-form-urlencoded para formularios, multipart/form-data para archivos.", noShuffle:false },
  { concept_id:"dwec_u7_q16", unit:7, question:"¿Qué es el 'long polling'?", options:["Hacer muchas peticiones por segundo","Una técnica donde el cliente envía una petición y el servidor la mantiene abierta hasta que hay datos nuevos que devolver","Una forma de comprimir las peticiones HTTP","Un tipo de WebSocket unidireccional"], correct:1, explanation:"Long polling es una emulación de push en HTTP: el cliente hace petición → servidor espera → responde cuando hay dato → cliente hace nueva petición inmediatamente.", noShuffle:false },
  { concept_id:"dwec_u7_q17", unit:7, question:"¿Para qué sirven las Server-Sent Events (SSE)?", options:["Para comunicación bidireccional en tiempo real","Para enviar un flujo unidireccional de eventos del servidor al cliente sobre HTTP","Para reemplazar a WebSockets","Para enviar ficheros grandes del servidor al cliente"], correct:1, explanation:"SSE (EventSource API) permite al servidor empujar eventos al cliente de forma unidireccional sobre HTTP. Más simple que WebSockets para notificaciones.", noShuffle:false },
  { concept_id:"dwec_u7_q18", unit:7, question:"¿Cuál es el propósito de la cabecera 'Authorization: Bearer token' en las APIs REST?", options:["Definir el tipo de contenido de la respuesta","Autenticar la petición enviando un token de acceso (JWT u OAuth)","Especificar el idioma preferido","Indicar la versión de la API"], correct:1, explanation:"Bearer token es el estándar para APIs REST autenticadas. El servidor valida el JWT u OAuth token para autorizar la operación.", noShuffle:false },
  { concept_id:"dwec_u7_q19", unit:7, question:"¿Qué devuelve fetch() si el servidor no está disponible (error de red)?", options:["Una respuesta con status 503","Una Promise rechazada con TypeError","null","Una respuesta vacía con status 0"], correct:1, explanation:"Errores de red (sin conexión, servidor caído) rechazan la Promise con TypeError. Los errores HTTP (404,500) resuelven la Promise (hay que comprobar response.ok).", noShuffle:false },
  { concept_id:"dwec_u7_q20", unit:7, question:"¿Qué hace AbortController en relación con fetch()?", options:["Controla el número máximo de peticiones simultáneas","Permite cancelar una petición fetch() en curso","Aborta el proceso del navegador si una petición falla","Reintenta la petición automáticamente si falla"], correct:1, explanation:"const controller = new AbortController(); fetch(url, {signal: controller.signal}); controller.abort(); — cancela la petición y rechaza la Promise con AbortError.", noShuffle:false },
  { concept_id:"dwec_u7_q21", unit:7, question:"¿Qué es un callback hell y cómo lo resuelven las Promises?", options:["Un error de memoria por demasiados callbacks","El problema de callbacks anidados profundamente que dificultan la legibilidad y el manejo de errores","Un tipo de ataque de seguridad","Un problema de rendimiento con muchas funciones"], correct:1, explanation:"Callbacks anidados son difíciles de leer y manejar errores en ellos. Las Promises permiten encadenamiento plano (.then().then()) y manejo centralizado con .catch().", noShuffle:false },
  { concept_id:"dwec_u7_q22", unit:7, question:"¿Cómo se puede enviar datos de formulario con fetch() incluyendo archivos?", options:["JSON.stringify(formData)","Usando un objeto FormData como body (sin establecer Content-Type)","Con body: formData.serialize()","Convirtiendo archivos a base64 manualmente"], correct:1, explanation:"const fd = new FormData(form); fetch(url, {method:'POST', body:fd}). No establecer Content-Type manualmente; fetch lo fija con el boundary correcto.", noShuffle:false },
  { concept_id:"dwec_u7_q23", unit:7, question:"¿Qué es la API de Cache del navegador y cómo se relaciona con los Service Workers?", options:["La caché del historial del navegador","Una API que permite a los Service Workers almacenar respuestas de red para uso offline","La caché de imágenes del navegador","Una API para almacenar JS en memoria"], correct:1, explanation:"Cache API + Service Worker = PWA offline. El SW intercepta fetch(), comprueba la cache, devuelve la respuesta cacheada o fetch desde red y cachea.", noShuffle:false },
  { concept_id:"dwec_u7_q24", unit:7, question:"¿Qué hace response.clone() en fetch()?", options:["Clona el objeto response para poder consumirlo más de una vez (un Response solo puede leerse una vez)","Crea una segunda petición al servidor","Copia los headers de la respuesta","Hace una copia local de los datos de la respuesta"], correct:0, explanation:"Response body se puede consumir una sola vez. clone() crea una copia antes de consumirlo, útil en Service Workers para cachear Y devolver la respuesta.", noShuffle:false },
  { concept_id:"dwec_u7_q25", unit:7, question:"¿Cómo funciona el encadenamiento de Promises con .then()?", options:["Cada .then() crea una Promise independiente","Cada .then() devuelve una nueva Promise, permitiendo encadenar operaciones asíncronas secuenciales","Las Promises en cadena se ejecutan en paralelo","Solo se puede tener un .then() por Promise"], correct:1, explanation:".then(fn) devuelve una nueva Promise con el valor retornado por fn. Si fn retorna una Promise, la cadena espera a que se resuelva.", noShuffle:false },
  { concept_id:"dwec_u7_q26", unit:7, question:"¿Cuál es la diferencia entre async/await y .then()/.catch()?", options:["async/await es más lento","Son equivalentes en funcionalidad; async/await tiene sintaxis más clara similar al código síncrono","async/await no puede manejar errores","Solo async/await soporta try/catch"], correct:1, explanation:"Ambos manejan Promises. async/await es azúcar sintáctico: más legible, usa try/catch nativo, facilita debugging. .then() es funcional y componible.", noShuffle:false },
  { concept_id:"dwec_u7_q27", unit:7, question:"¿Qué es GraphQL y en qué se diferencia de REST?", options:["Es más lento que REST siempre","Un lenguaje de consulta de APIs donde el cliente especifica exactamente qué datos necesita, en una sola petición","Un protocolo de seguridad para APIs","Un tipo de base de datos NoSQL"], correct:1, explanation:"REST: múltiples endpoints fijos. GraphQL: un endpoint, el cliente define la query. Evita over-fetching (recibir más datos de los necesarios) y under-fetching.", noShuffle:false },
  { concept_id:"dwec_u7_q28", unit:7, question:"¿Qué hace el método .finally() en una Promise?", options:["Solo se ejecuta si la Promise es rechazada","Solo se ejecuta si la Promise es resuelta","Se ejecuta siempre, independientemente del resultado, para limpieza de recursos","Finaliza todas las Promises pendientes"], correct:2, explanation:".finally(fn) es como try/catch/finally: útil para ocultar spinners, cerrar conexiones, etc. No recibe el valor ni el error.", noShuffle:false },
  { concept_id:"dwec_u7_q29", unit:7, question:"¿Cómo se puede reintentar automáticamente una petición fetch() fallida?", options:["fetch tiene un parámetro 'retry'","Implementando una función recursiva o con un bucle que llama a fetch() de nuevo en el .catch()","Los navegadores reintentan automáticamente","No se puede reintentar con fetch()"], correct:1, explanation:"async function fetchWithRetry(url, n=3){ try{ return await fetch(url); } catch(e){ if(n>0) return fetchWithRetry(url,n-1); throw e; } }", noShuffle:false },
  { concept_id:"dwec_u7_q30", unit:7, question:"¿Qué es JSONP y por qué es obsoleto?", options:["Un formato JSON mejorado con padding","Una técnica antigua para peticiones cross-origin usando <script> tags; obsoleto porque CORS lo reemplaza de forma segura","Una librería de jQuery para peticiones JSON","Un tipo de JWT modificado"], correct:1, explanation:"JSONP inyectaba scripts de otro dominio en un callback. Fue reemplazado por CORS que es más seguro, flexible y estándar.", noShuffle:false },
  { concept_id:"dwec_u7_q31", unit:7, question:"¿Qué hace Promise.resolve(valor)?", options:["Crea una Promise que siempre rechaza","Crea una Promise ya resuelta con el valor dado","Fuerza la resolución de una Promise pendiente","Es equivalente a new Promise((r)=>r(valor)) pero más rápido"], correct:1, explanation:"Promise.resolve(42) crea una Promise resuelta. Útil para normalizar valores que pueden ser síncronos o asincrónicos. Si el valor es una Promise, devuelve esa misma.", noShuffle:false },
  { concept_id:"dwec_u7_q32", unit:7, question:"¿Qué información proporciona la cabecera 'Content-Length' en una respuesta HTTP?", options:["El tiempo que tardó en generarse la respuesta","El tamaño en bytes del cuerpo de la respuesta","El número de recursos incluidos en la respuesta","La versión del servidor web"], correct:1, explanation:"Content-Length indica el tamaño del cuerpo. Permite mostrar progreso de descarga. Si no está presente, el cuerpo puede enviarse en chunks (Transfer-Encoding: chunked).", noShuffle:false },
  { concept_id:"dwec_u7_q33", unit:7, question:"¿Cómo se puede usar fetch() con autenticación básica HTTP?", options:["fetch(url, {auth: user+':'+pass})","fetch(url, {headers: {Authorization: 'Basic '+btoa(usuario+':'+contraseña)}})","fetch.authenticate(url, user, pass)","No es posible con fetch()"], correct:1, explanation:"btoa() convierte a Base64. La cabecera Authorization: Basic BASE64(user:pass) es el formato de HTTP Basic Auth.", noShuffle:false },
  { concept_id:"dwec_u7_q34", unit:7, question:"¿Cuál es el código de estado HTTP para 'Creado exitosamente' tras un POST?", options:["200","201","204","202"], correct:1, explanation:"201 Created es la respuesta estándar tras crear un recurso con POST. 200 OK para operaciones exitosas generales. 204 No Content si no hay cuerpo en la respuesta.", noShuffle:false },
  { concept_id:"dwec_u7_q35", unit:7, question:"¿Qué es el patrón Repository en el contexto de peticiones de datos?", options:["Un backup de datos en el servidor","Una capa de abstracción que encapsula el acceso a datos (fetch/API), desacoplándolo del resto de la aplicación","Un tipo de caché de respuestas HTTP","Una forma de organizar el código en carpetas"], correct:1, explanation:"El patrón Repository: const userRepo = { getAll: ()=>fetch('/api/users').then(r=>r.json()), create: (u)=>fetch('/api/users',{method:'POST',...}) }", noShuffle:false },
  { concept_id:"dwec_u7_q36", unit:7, question:"¿Cómo se puede medir el tiempo de una petición fetch()?", options:["fetch devuelve el tiempo en la respuesta","Con performance.now() antes y después de la petición (o usando PerformanceObserver)","Con Date.now() en el servidor","No es posible medir el tiempo de fetch()"], correct:1, explanation:"const t0=performance.now(); await fetch(url); console.log(performance.now()-t0). Performance API da microsegundos de precisión.", noShuffle:false },
  { concept_id:"dwec_u7_q37", unit:7, question:"¿Qué cabecera HTTP permite al servidor indicar durante cuánto tiempo una respuesta puede ser cacheada?", options:["Expires","Cache-Control (max-age=N segundos)","ETag","Last-Modified"], correct:1, explanation:"Cache-Control: max-age=3600 indica que la respuesta puede cachearse 1 hora. ETag y Last-Modified se usan para validación de caché condicional.", noShuffle:false },
  { concept_id:"dwec_u7_q38", unit:7, question:"¿Qué es XMLHttpRequest y en qué se diferencia de fetch()?", options:["XMLHttpRequest es más moderno que fetch","XHR es la API original de AJAX (callback-based, verbosa); fetch es moderna (Promise-based, más limpia)","XHR solo acepta XML; fetch solo JSON","No hay diferencias significativas"], correct:1, explanation:"XHR se creó en IE5 (1999). fetch es ES2015. XHR tiene más control (progress events, abortar). fetch es más limpio con async/await.", noShuffle:false },
  { concept_id:"dwec_u7_q39", unit:7, question:"¿Cuándo se usa Promise.allSettled() en lugar de Promise.all()?", options:["Cuando solo necesitamos el primero que resuelva","Cuando necesitamos los resultados de TODAS las promises aunque algunas fallen (sin cortocircuito)","Cuando las promises son independientes","Cuando las promises devuelven strings"], correct:1, explanation:"allSettled() devuelve array de {status:'fulfilled'|'rejected', value|reason}. Útil para múltiples operaciones independientes donde el fallo de una no debe cancelar las demás.", noShuffle:false },
  { concept_id:"dwec_u7_q40", unit:7, question:"¿Qué es un interceptor de peticiones HTTP?", options:["Un firewall que bloquea peticiones no autorizadas","Middleware que intercepta peticiones/respuestas para añadir headers, logging o transformación antes de que lleguen al código","Un tipo especial de proxy inverso","Un plugin del navegador"], correct:1, explanation:"Librerías como Axios permiten interceptores: axios.interceptors.request.use(config=>{config.headers.Authorization=token; return config;});", noShuffle:false },
  { concept_id:"dwec_u7_q41", unit:7, question:"¿Qué es streaming de respuestas con fetch() (response.body)?", options:["Reproducir vídeo con fetch","Leer la respuesta de forma incremental usando ReadableStream en lugar de esperar a que llegue completa","Una forma de enviar datos en múltiples peticiones","El streaming de WebSockets sobre HTTP"], correct:1, explanation:"response.body es un ReadableStream. const reader = response.body.getReader(); while(true){ const {done,value}=await reader.read(); ... }. Útil para respuestas IA grandes.", noShuffle:false },
  { concept_id:"dwec_u7_q42", unit:7, question:"¿Cuál es la diferencia entre una petición 'simple' y una 'preflighted' en CORS?", options:["No hay diferencia","Las simples no necesitan preflight (GET/POST con tipos comunes); las no-simples envían primero OPTIONS para pedir permiso al servidor","Las preflighted son más seguras siempre","Las simples son más rápidas y las preflighted más seguras"], correct:1, explanation:"Preflight: peticiones con métodos no-simples (PUT,DELETE) o headers personalizados envían OPTIONS previo. Si el servidor lo acepta, se hace la petición real.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 8 — Almacenamiento en el cliente
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dwec_u8_q1", unit:8, question:"¿Cuál es la diferencia entre localStorage y sessionStorage?", options:["localStorage persiste indefinidamente; sessionStorage solo durante la sesión del navegador","sessionStorage almacena más datos","localStorage es más seguro","Ambos se borran al cerrar el navegador"], correct:0, explanation:"localStorage: persiste aunque se cierre el navegador. sessionStorage: se borra al cerrar la pestaña. Ambos: ~5-10MB, mismo origen.", noShuffle:false },
  { concept_id:"dwec_u8_q2", unit:8, question:"¿Cómo se guarda un objeto en localStorage?", options:["localStorage.setItem('k', objeto)","localStorage.setItem('k', JSON.stringify(objeto))","localStorage.save('k', objeto)","localStorage['k'] = objeto"], correct:1, explanation:"localStorage solo almacena strings. JSON.stringify() serializa objetos. JSON.parse() los recupera.", noShuffle:false },
  { concept_id:"dwec_u8_q3", unit:8, question:"¿Qué son las cookies y cuál es su principal uso?", options:["Archivos de imagen del servidor","Pequeños datos en el navegador enviados al servidor en cada petición HTTP; usados para sesiones y rastreo","Scripts maliciosos","API para almacenar grandes cantidades de datos"], correct:1, explanation:"Cookies: pares nombre=valor. Se envían automáticamente en cada petición al dominio. Útiles para sesiones. Límite ~4KB.", noShuffle:false },
  { concept_id:"dwec_u8_q4", unit:8, question:"¿Qué es un Service Worker?", options:["Un empleado de soporte técnico","Script en hilo separado, proxy entre app y red, permite offline y notificaciones push","API para controlar Web Workers del servidor","Framework para apps en segundo plano"], correct:1, explanation:"Service Workers: hilo separado (sin acceso al DOM), interceptan peticiones, gestionan caché. Base de las PWA.", noShuffle:false },
  { concept_id:"dwec_u8_q5", unit:8, question:"¿Qué es una PWA (Progressive Web App)?", options:["Un servidor web optimizado","App web con experiencia similar a nativa: offline, instalable, notificaciones push","Framework CSS responsive","Extensión del navegador"], correct:1, explanation:"PWAs combinan Service Worker + Web App Manifest + HTTPS para instalación, offline y notificaciones.", noShuffle:false },
  { concept_id:"dwec_u8_q6", unit:8, question:"¿Cuál es la capacidad de almacenamiento aproximada de localStorage?", options:["4KB como las cookies","5-10MB por origen","100MB por origen","Ilimitada"], correct:1, explanation:"localStorage: ~5MB en la mayoría de navegadores (algunos permiten más). El límite exacto varía. Cookies: ~4KB. IndexedDB: mucho mayor.", noShuffle:false },
  { concept_id:"dwec_u8_q7", unit:8, question:"¿Cómo se accede al localStorage en JavaScript?", options:["window.storage","window.localStorage o directamente localStorage","Storage.local","browser.localStorage"], correct:1, explanation:"localStorage es una propiedad de window. Se puede usar directamente (window es implícito en el navegador).", noShuffle:false },
  { concept_id:"dwec_u8_q8", unit:8, question:"¿Cuáles son los métodos disponibles en localStorage?", options:["get(), set(), del(), clear()","setItem(), getItem(), removeItem(), clear(), key()","save(), load(), delete(), reset()","write(), read(), erase(), empty()"], correct:1, explanation:"localStorage.setItem(k,v), getItem(k) (null si no existe), removeItem(k), clear() (borra todo), length y key(n).", noShuffle:false },
  { concept_id:"dwec_u8_q9", unit:8, question:"¿Qué es IndexedDB?", options:["Una base de datos SQL en el cliente","Una base de datos NoSQL asíncrona en el cliente para grandes cantidades de datos estructurados","Un tipo especial de localStorage","Una API para acceder a bases de datos de Node.js"], correct:1, explanation:"IndexedDB: BD NoSQL en el navegador, asíncrona, soporta transacciones, índices y grandes volúmenes. API compleja; se usa con Dexie.js o idb.", noShuffle:false },
  { concept_id:"dwec_u8_q10", unit:8, question:"¿Qué ventaja tiene indexedDB sobre localStorage?", options:["IndexedDB es síncrono y más rápido","IndexedDB soporta tipos complejos, transacciones, índices y grandes volúmenes sin bloquear el hilo principal","localStorage tiene capacidad ilimitada","No hay ventaja, localStorage es siempre mejor"], correct:1, explanation:"localStorage: síncrono (bloquea), solo strings, ~5MB. IndexedDB: asíncrono, objetos JS nativos, GBs de datos, búsquedas con índices.", noShuffle:false },
  { concept_id:"dwec_u8_q11", unit:8, question:"¿Qué evento se dispara cuando localStorage cambia en otra pestaña del mismo origen?", options:["localStorage.change","window.onstorage (evento 'storage')","storage.update","localStorageEvent"], correct:1, explanation:"window.addEventListener('storage', fn) detecta cambios de localStorage realizados en OTRAS pestañas/ventanas del mismo origen. No se dispara en la propia pestaña.", noShuffle:false },
  { concept_id:"dwec_u8_q12", unit:8, question:"¿Cuál es el ciclo de vida de un Service Worker?", options:["Install → Start → Stop","Install → Activate → Fetch (intercepta peticiones)","Register → Run → Terminate","Download → Parse → Execute"], correct:1, explanation:"1) register() en el cliente. 2) install (caché recursos). 3) activate (limpiar caché antigua). 4) fetch (interceptar peticiones). 5) sync, push...", noShuffle:false },
  { concept_id:"dwec_u8_q13", unit:8, question:"¿Qué hace caches.open('v1') en un Service Worker?", options:["Abre la caché del navegador","Abre (o crea) un objeto Cache con el nombre 'v1' para almacenar respuestas HTTP","Abre IndexedDB con nombre v1","Activa la versión v1 del Service Worker"], correct:1, explanation:"Cache API: caches.open() devuelve una Promise con el objeto Cache. cache.put(request, response), cache.match(), cache.delete().", noShuffle:false },
  { concept_id:"dwec_u8_q14", unit:8, question:"¿Cómo se registra un Service Worker en una página web?", options:["<script type='service-worker' src='sw.js'>","navigator.serviceWorker.register('/sw.js')","ServiceWorker.install('/sw.js')","window.installSW('/sw.js')"], correct:1, explanation:"if('serviceWorker' in navigator){ navigator.serviceWorker.register('/sw.js').then(...).catch(...); }", noShuffle:false },
  { concept_id:"dwec_u8_q15", unit:8, question:"¿Qué es el Web App Manifest?", options:["Un archivo de configuración de Apache para PWAs","Un archivo JSON que describe la PWA (nombre, iconos, colores, modo de visualización) para instalación en el dispositivo","Un certificado SSL para PWAs","El manifiesto de permisos de la aplicación"], correct:1, explanation:"manifest.json (o .webmanifest): define name, short_name, icons, start_url, display (standalone/fullscreen), theme_color, background_color.", noShuffle:false },
  { concept_id:"dwec_u8_q16", unit:8, question:"¿Cuáles son los atributos de una cookie que aumentan su seguridad?", options:["secure=true y noCache=true","Secure (solo HTTPS), HttpOnly (no accesible con JS), SameSite (protege CSRF)","Private=true y Encrypted=true","Protected y Signed"], correct:1, explanation:"Secure: solo en HTTPS. HttpOnly: no accesible con document.cookie (protege de XSS). SameSite=Strict/Lax: protege de CSRF.", noShuffle:false },
  { concept_id:"dwec_u8_q17", unit:8, question:"¿Para qué se usa el atributo 'expires' o 'max-age' en una cookie?", options:["Para determinar el tamaño máximo","Para definir cuándo expira la cookie (sin ellos es de sesión y se borra al cerrar el navegador)","Para indicar el servidor que la creó","Para establecer el dominio de la cookie"], correct:1, explanation:"Sin expires/max-age: cookie de sesión (volátil). Con fecha futura: cookie persistente. max-age=0 o fecha pasada: elimina la cookie.", noShuffle:false },
  { concept_id:"dwec_u8_q18", unit:8, question:"¿Cómo se implementa la estrategia 'Cache First' en un Service Worker?", options:["Buscar primero en la red y si falla usar caché","Buscar primero en caché; si no está, ir a la red y cachear la respuesta","Siempre ir a la red, ignorar caché","Mezclar caché y red en paralelo"], correct:1, explanation:"Cache First: caches.match(req) → si acierto, devolver. Si no, fetch(req), cachear respuesta, devolver. Óptimo para assets estáticos.", noShuffle:false },
  { concept_id:"dwec_u8_q19", unit:8, question:"¿Cuál es la diferencia entre la estrategia 'Network First' y 'Cache First'?", options:["Network First es para texto; Cache First para imágenes","Network First prioriza datos frescos de red (con fallback a caché); Cache First prioriza velocidad (con fallback a red)","Son equivalentes con diferente nombre","Network First no funciona offline"], correct:1, explanation:"Network First: ideal para APIs que necesitan datos actualizados. Cache First: ideal para assets que raramente cambian. Stale While Revalidate: devuelve caché y actualiza en background.", noShuffle:false },
  { concept_id:"dwec_u8_q20", unit:8, question:"¿Qué es Web Storage API?", options:["Una API para acceder al sistema de ficheros","La API que incluye localStorage y sessionStorage para almacenar strings clave-valor en el navegador","Una API para almacenamiento en la nube","Una extensión de las cookies"], correct:1, explanation:"Web Storage API (HTML5) define localStorage y sessionStorage. Más cómoda que cookies para datos que no necesitan enviarse al servidor.", noShuffle:false },
  { concept_id:"dwec_u8_q21", unit:8, question:"¿Qué es Background Sync en el contexto de Service Workers?", options:["Una forma de sincronizar datos en segundo plano incluso cuando la app está cerrada, cuando se recupera la conexión","Un timer que ejecuta el SW periódicamente","La sincronización entre múltiples pestañas","La actualización automática del SW"], correct:0, explanation:"Background Sync: el SW registra un sync task. Cuando hay conexión (aunque la app esté cerrada), el SW dispara el evento 'sync' para completar operaciones pendientes.", noShuffle:false },
  { concept_id:"dwec_u8_q22", unit:8, question:"¿Qué son las Push Notifications en PWAs?", options:["Notificaciones que aparecen dentro de la app","Notificaciones enviadas por el servidor al dispositivo del usuario incluso con la app cerrada, gestionadas por el SW","Mensajes entre pestañas de la misma app","Alertas generadas por el sistema operativo"], correct:1, explanation:"Push: servidor envía mensaje a través de Push Service del navegador → SW recibe evento 'push' → muestra Notification aunque la app esté cerrada.", noShuffle:false },
  { concept_id:"dwec_u8_q23", unit:8, question:"¿Cuál es la limitación principal de localStorage en comparación con IndexedDB?", options:["localStorage es más lento","localStorage es síncrono (bloquea el hilo), solo almacena strings y tiene capacidad limitada (~5MB)","localStorage no funciona offline","localStorage no es compatible con Safari"], correct:1, explanation:"Para datos simples no-críticos: localStorage. Para datos complejos, grandes volúmenes o uso frecuente: IndexedDB (asíncrono, no bloquea).", noShuffle:false },
  { concept_id:"dwec_u8_q24", unit:8, question:"¿Cómo se puede compartir datos entre Service Worker y la página cliente?", options:["Con localStorage","Con postMessage() y BroadcastChannel API","Con variables globales","Con cookies"], correct:1, explanation:"SW y clientes pueden comunicarse con postMessage(). BroadcastChannel permite que el SW transmita mensajes a todos los clientes del origen.", noShuffle:false },
  { concept_id:"dwec_u8_q25", unit:8, question:"¿Qué es el File System Access API?", options:["Una API para acceder a archivos remotos","Una API web moderna que permite a las aplicaciones web leer y escribir en el sistema de archivos local del usuario (con permiso)","Una API para gestionar uploads en el servidor","El atributo 'download' en los enlaces"], correct:1, explanation:"File System Access API (Chromium): showOpenFilePicker(), showSaveFilePicker() permiten abrir/guardar archivos locales. No disponible en todos los navegadores.", noShuffle:false },
  { concept_id:"dwec_u8_q26", unit:8, question:"¿Qué diferencia hay entre cookies de sesión y cookies persistentes?", options:["No hay diferencia, son el mismo tipo","Sesión: se borran al cerrar el navegador. Persistentes: tienen fecha de expiración y permanecen entre sesiones","Sesión: almacenadas en RAM. Persistentes: en disco","Las persistentes son más seguras"], correct:1, explanation:"Sin atributo expires/max-age → sesión (en memoria, volátil). Con expires en el futuro → persistente (en disco). Para recordar sesión de usuario: persistente.", noShuffle:false },
  { concept_id:"dwec_u8_q27", unit:8, question:"¿Qué problema de privacidad tienen las cookies de terceros?", options:["Ocupan demasiado espacio","Permiten el rastreo del usuario entre diferentes sitios web (cross-site tracking)","Son menos seguras que localStorage","No se pueden leer desde JavaScript"], correct:1, explanation:"Las cookies de terceros (ej: pixels de tracking de Facebook en cualquier web) permiten a un dominio externo rastrear al usuario. Los navegadores las están eliminando.", noShuffle:false },
  { concept_id:"dwec_u8_q28", unit:8, question:"¿Qué hace localStorage.clear()?", options:["Limpia solo los datos expirados","Elimina TODOS los datos de localStorage del origen actual","Formatea el valor de cada entrada a null","Reinicia el navegador"], correct:1, explanation:"clear() vacía todo el localStorage del origen. removeItem('key') elimina solo una entrada. Para borrar una cookie: establecer expires en el pasado.", noShuffle:false },
  { concept_id:"dwec_u8_q29", unit:8, question:"¿Cómo se puede implementar almacenamiento offline en una PWA?", options:["Usando solo localStorage para todos los datos","Combinando Service Worker (para interceptar peticiones) + Cache API (para respuestas) + IndexedDB (para datos de la app)","Deshabilitando la conexión a internet de la app","Con un servidor local en el dispositivo"], correct:1, explanation:"Estrategia completa: SW cachea recursos estáticos en install. Cachea respuestas de API en fetch. IndexedDB guarda datos del usuario. SW sirve desde caché cuando offline.", noShuffle:false },
  { concept_id:"dwec_u8_q30", unit:8, question:"¿Qué es el Lighthouse score de una PWA?", options:["Una puntuación de seguridad de las cookies","Una herramienta de Google (integrada en Chrome DevTools) que audita el rendimiento, accesibilidad, SEO y características PWA","Un sistema de puntuación de usuarios","Una métrica del número de notificaciones push recibidas"], correct:1, explanation:"Lighthouse audita: Performance (Core Web Vitals), Accessibility, Best Practices, SEO y Progressive Web App. Genera un informe con puntuaciones y recomendaciones.", noShuffle:false },
  { concept_id:"dwec_u8_q31", unit:8, question:"¿Qué es el Workbox de Google?", options:["Una herramienta para generar PWA manifests","Una librería que simplifica la creación de Service Workers con estrategias de caché predefinidas","Un emulador de service workers para testing","Una API de notificaciones para PWA"], correct:1, explanation:"Workbox (Google) abstrae la complejidad de los SW: workbox.routing.registerRoute(), workbox.strategies.CacheFirst() sin escribir el SW desde cero.", noShuffle:false },
  { concept_id:"dwec_u8_q32", unit:8, question:"¿Qué propiedad del navigator indica si el dispositivo tiene conexión a internet?", options:["navigator.connection","navigator.onLine","navigator.network.status","navigator.hasInternet"], correct:1, explanation:"navigator.onLine → boolean. Se complementa con window.addEventListener('online'/'offline', fn). No distingue entre conexión real a internet y red local.", noShuffle:false },
  { concept_id:"dwec_u8_q33", unit:8, question:"¿Cómo se puede detectar cuándo el SW tiene una nueva versión disponible?", options:["El navegador lo notifica automáticamente con un alert","navigator.serviceWorker.addEventListener('controllerchange') o la propiedad registration.waiting","Con localStorage.version","Con un polling al servidor cada hora"], correct:1, explanation:"Cuando hay un SW nuevo esperando (waiting), se puede notificar al usuario y llamar skipWaiting() para activarlo. controllerchange se dispara cuando el SW nuevo toma el control.", noShuffle:false },
  { concept_id:"dwec_u8_q34", unit:8, question:"¿Qué hace self.skipWaiting() en un Service Worker?", options:["Pausa el Service Worker temporalmente","Hace que el SW en estado 'waiting' omita la espera y pase directamente a 'active' sin necesitar que el usuario cierre las pestañas","Elimina el Service Worker instalado","Actualiza el Service Worker desde el servidor"], correct:1, explanation:"Por defecto, un SW nuevo espera a que todas las pestañas usen el SW antiguo se cierren. skipWaiting() fuerza la activación inmediata.", noShuffle:false },
  { concept_id:"dwec_u8_q35", unit:8, question:"¿Para qué sirve el evento 'activate' de un Service Worker?", options:["Se ejecuta cuando el usuario abre la app","Para limpiar cachés antiguas de versiones anteriores del SW","Para interceptar las primeras peticiones del cliente","Para registrar el SW en el servidor de push"], correct:1, explanation:"En activate: self.addEventListener('activate', e=>{ e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE_V).map(k=>caches.delete(k))))); });", noShuffle:false },
  { concept_id:"dwec_u8_q36", unit:8, question:"¿Cómo se itera sobre todas las entradas de localStorage?", options:["localStorage.forEach()","Usando localStorage.length y localStorage.key(i) en un bucle for","Object.keys(localStorage).forEach()","No es posible iterar localStorage"], correct:1, explanation:"for(let i=0; i<localStorage.length; i++){ const key=localStorage.key(i); const val=localStorage.getItem(key); }. O: Object.entries(localStorage).", noShuffle:false },
  { concept_id:"dwec_u8_q37", unit:8, question:"¿Qué restricción de seguridad se aplica a Service Workers?", options:["Solo pueden ejecutarse con el usuario administrador","Solo funcionan con HTTPS (o localhost para desarrollo)","Solo pueden gestionar el dominio principal, no subdominios","Necesitan permiso explícito del usuario para instalarse"], correct:1, explanation:"Los SWs requieren HTTPS por seguridad (podrían interceptar todas las peticiones). En localhost, funciona sin HTTPS para desarrollo.", noShuffle:false },
  { concept_id:"dwec_u8_q38", unit:8, question:"¿Qué es la estrategia 'Stale While Revalidate' en Service Workers?", options:["Devuelve siempre datos desactualizados","Devuelve la respuesta de caché inmediatamente (aunque sea antigua) y en paralelo actualiza la caché desde la red","Solo sirve datos cuando la caché es reciente","Combina Network First y Cache First aleatoriamente"], correct:1, explanation:"SWR: velocidad máxima (respuesta inmediata de caché) + datos frescos (actualización en background). Ideal para datos que cambian pero donde un segundo retraso es aceptable.", noShuffle:false },
  { concept_id:"dwec_u8_q39", unit:8, question:"¿Cómo se puede verificar si una app está instalada como PWA?", options:["window.isPWA","window.matchMedia('(display-mode: standalone)').matches","navigator.standalone (Safari) o querystring ?pwa=1","No hay forma estándar de verificarlo"], correct:1, explanation:"window.matchMedia('(display-mode: standalone)').matches → true si está instalada. También: navigator.standalone (iOS Safari). Útil para mostrar el botón 'Instalar' solo si no está instalada.", noShuffle:false },
  { concept_id:"dwec_u8_q40", unit:8, question:"¿Cómo se puede implementar el botón 'Agregar a pantalla de inicio' para una PWA?", options:["Con el atributo install en el <link> del manifest","Capturando el evento 'beforeinstallprompt' y llamando a prompt() cuando el usuario quiera instalar","Con una etiqueta <install-pwa> en HTML","Es automático, no requiere código"], correct:1, explanation:"window.addEventListener('beforeinstallprompt', e=>{ e.preventDefault(); deferredPrompt=e; }); // luego: deferredPrompt.prompt() en el click del botón.", noShuffle:false },
  { concept_id:"dwec_u8_q41", unit:8, question:"¿Qué es el 'scope' de un Service Worker?", options:["La memoria RAM que puede usar el SW","El conjunto de URLs que puede controlar el SW, determinado por su ubicación en el servidor","El tiempo máximo que puede ejecutarse","El número máximo de peticiones que puede interceptar"], correct:1, explanation:"Un SW en /app/sw.js controla solo URLs bajo /app/. Un SW en /sw.js controla todo el origen. Se puede ajustar con la opción scope en register().", noShuffle:false },
  { concept_id:"dwec_u8_q42", unit:8, question:"¿Cómo se puede compartir el estado entre múltiples pestañas de una PWA?", options:["Con window.shared","Con BroadcastChannel API, localStorage (con evento 'storage') o SharedWorker","Con cookies de sesión sincronizadas","No es posible compartir estado entre pestañas"], correct:1, explanation:"BroadcastChannel: const ch=new BroadcastChannel('app'); ch.postMessage(data); ch.onmessage=e=>{}. SharedWorker: un worker compartido entre múltiples contextos.", noShuffle:false },

  // ════════════════════════════════════════════════════════════════
  //  UNIDAD 9 — Multimedia y Geolocalización
  // ════════════════════════════════════════════════════════════════
  { concept_id:"dwec_u9_q1", unit:9, question:"¿Qué API permite acceder a la posición geográfica del usuario?", options:["navigator.location","window.gps","navigator.geolocation","document.position"], correct:2, explanation:"navigator.geolocation proporciona acceso a la posición mediante GPS, WiFi o triangulación. Requiere permiso explícito del usuario.", noShuffle:false },
  { concept_id:"dwec_u9_q2", unit:9, question:"¿Qué método obtiene la posición actual UNA sola vez?", options:["watchPosition()","getCurrentPosition()","getLocation()","trackPosition()"], correct:1, explanation:"getCurrentPosition(success, error, options): obtiene una vez. watchPosition(): monitoriza cambios y llama al callback cada vez que la posición cambia.", noShuffle:false },
  { concept_id:"dwec_u9_q3", unit:9, question:"¿Cuáles son los atributos mínimos del objeto Position de la Geolocation API?", options:["x, y, altitude","coords.latitude, coords.longitude, timestamp","lat, lng, accuracy","position.x, position.y, position.z"], correct:1, explanation:"Position: coords (latitude, longitude, accuracy obligatorios; altitude, altitudeAccuracy, heading, speed opcionales) y timestamp.", noShuffle:false },
  { concept_id:"dwec_u9_q4", unit:9, question:"¿Qué elementos HTML5 permiten reproducir audio y vídeo sin plugins externos?", options:["<media> y <play>","<embed> y <object>","<audio> y <video>","<sound> y <film>"], correct:2, explanation:"HTML5 introdujo <audio> y <video> con API JS nativa, eliminando la necesidad de Flash.", noShuffle:false },
  { concept_id:"dwec_u9_q5", unit:9, question:"¿Qué propiedad de un elemento <video> inicia la reproducción automática?", options:["autoplay","autostart","play","start"], correct:0, explanation:"El atributo autoplay. Los navegadores modernos suelen bloquearlo salvo que el vídeo esté silenciado (muted). Recomendación: autoplay + muted.", noShuffle:false },
  { concept_id:"dwec_u9_q6", unit:9, question:"¿Cómo se detiene la reproducción de un vídeo desde JavaScript?", options:["video.stop()","video.pause()","video.end()","video.halt()"], correct:1, explanation:"video.play() inicia. video.pause() pausa (no hay stop nativo; equivalente: video.pause(); video.currentTime=0;).", noShuffle:false },
  { concept_id:"dwec_u9_q7", unit:9, question:"¿Qué hace watchPosition() en la Geolocation API?", options:["Guarda la posición en localStorage","Registra un listener que recibe la posición cada vez que cambia","Muestra la posición en un mapa","Establece un límite de precisión para la posición"], correct:1, explanation:"watchPosition() devuelve un ID. Para detenerlo: clearWatch(id). Similar a setInterval pero para posición GPS.", noShuffle:false },
  { concept_id:"dwec_u9_q8", unit:9, question:"¿Qué formatos de vídeo soportan los navegadores modernos de forma nativa?", options:["AVI, MOV, FLV","MP4 (H.264), WebM (VP9/AV1), Ogg Theora","Solo MP4","Solo WebM"], correct:1, explanation:"MP4/H.264: amplio soporte. WebM: formato abierto de Google. Ogg: formato libre. Con <source> se pueden ofrecer múltiples formatos para compatibilidad.", noShuffle:false },
  { concept_id:"dwec_u9_q9", unit:9, question:"¿Qué API de JavaScript permite acceder a la cámara y micrófono del usuario?", options:["Camera API","getUserMedia() (parte de MediaDevices API)","HTMLMediaElement","navigator.camera"], correct:1, explanation:"navigator.mediaDevices.getUserMedia({video:true, audio:true}) → Promise con MediaStream. Luego: video.srcObject = stream.", noShuffle:false },
  { concept_id:"dwec_u9_q10", unit:9, question:"¿Qué es el Canvas API en JavaScript?", options:["Una librería de CSS para dibujar","Una API HTML5 que permite dibujar gráficos 2D/3D (WebGL) en un elemento <canvas> mediante JavaScript","Un elemento HTML para mostrar imágenes SVG","Una API para animaciones CSS"], correct:1, explanation:"canvas.getContext('2d') → CanvasRenderingContext2D para dibujar. Para 3D: getContext('webgl') o getContext('webgl2').", noShuffle:false },
  { concept_id:"dwec_u9_q11", unit:9, question:"¿Para qué sirve la API Web Audio?", options:["Para reproducir podcasts","Para procesar, sintetizar y analizar audio en tiempo real desde JavaScript con alto rendimiento","Para convertir texto a audio","Para gestionar la playlist del elemento <audio>"], correct:1, explanation:"Web Audio API: sintetizadores, efectos en tiempo real, visualizadores (FFT), análisis de frecuencias. AudioContext, OscillatorNode, GainNode, AnalyserNode.", noShuffle:false },
  { concept_id:"dwec_u9_q12", unit:9, question:"¿Qué hace la propiedad video.currentTime?", options:["Devuelve la duración total del vídeo","Devuelve o establece la posición de reproducción actual en segundos","Devuelve el tiempo en formato HH:MM:SS","Controla la velocidad de reproducción"], correct:1, explanation:"video.currentTime = 30 salta al segundo 30. video.duration es la duración total. video.playbackRate controla la velocidad.", noShuffle:false },
  { concept_id:"dwec_u9_q13", unit:9, question:"¿Qué evento se dispara cuando un vídeo termina de reproducirse?", options:["video.onfinish","video.addEventListener('ended', fn)","video.oncomplete","video.done"], correct:1, explanation:"El evento 'ended' se dispara cuando el vídeo llega al final. También: 'play', 'pause', 'timeupdate', 'waiting', 'canplay', 'loadedmetadata'.", noShuffle:false },
  { concept_id:"dwec_u9_q14", unit:9, question:"¿Cuál es la diferencia entre la propiedad 'accuracy' y 'altitude' en la Geolocation API?", options:["Son lo mismo","accuracy: precisión horizontal en metros; altitude: altura sobre el nivel del mar en metros (puede ser null)","altitude es obligatorio; accuracy es opcional","accuracy es para GPS; altitude para WiFi"], correct:1, explanation:"coords.accuracy (metros, obligatorio). coords.altitude (metros sobre el nivel del mar, null si no disponible). coords.altitudeAccuracy (precisión de la altitud, null si no disponible).", noShuffle:false },
  { concept_id:"dwec_u9_q15", unit:9, question:"¿Qué hace navigator.geolocation.clearWatch(watchId)?", options:["Borra el historial de posiciones","Cancela el observador de posición registrado con watchPosition()","Limpia la caché de geolocalización","Resetea la precisión del GPS"], correct:1, explanation:"clearWatch(id) cancela el watchPosition() asociado al id. Equivalente a clearInterval() para los setInterval.", noShuffle:false },
  { concept_id:"dwec_u9_q16", unit:9, question:"¿Qué propiedad del objeto options de getCurrentPosition() indica la precisión deseada?", options:["precision: 'high'","enableHighAccuracy: true","accuracy: 'gps'","mode: 'precise'"], correct:1, explanation:"options: { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }. enableHighAccuracy usa GPS (más lento y consume batería) en lugar de WiFi/red.", noShuffle:false },
  { concept_id:"dwec_u9_q17", unit:9, question:"¿Qué es WebRTC?", options:["Un codec de vídeo para HTML5","Una API que permite comunicación en tiempo real entre navegadores (vídeo, audio, datos P2P) sin plugins","Un protocolo de streaming de vídeo","Una API para capturar la pantalla"], correct:1, explanation:"WebRTC (Web Real-Time Communication): videoconferencia entre navegadores (peer-to-peer). Base de Google Meet, Jitsi, etc. RTCPeerConnection, RTCDataChannel.", noShuffle:false },
  { concept_id:"dwec_u9_q18", unit:9, question:"¿Para qué sirve la Fullscreen API en JavaScript?", options:["Para maximizar la ventana del navegador","Para mostrar un elemento HTML en pantalla completa (sin la interfaz del navegador)","Para crear presentaciones a pantalla completa","Para cambiar la resolución de la pantalla"], correct:1, explanation:"element.requestFullscreen(). document.exitFullscreen(). document.fullscreenElement indica el elemento en pantalla completa. Evento: fullscreenchange.", noShuffle:false },
  { concept_id:"dwec_u9_q19", unit:9, question:"¿Qué hace la propiedad video.volume?", options:["Devuelve el número de canales de audio","Controla el volumen del vídeo: valor entre 0 (silencio) y 1 (máximo)","Devuelve el formato de audio del vídeo","Controla el balance izquierda-derecha del audio"], correct:1, explanation:"video.volume = 0.5 → 50% de volumen. video.muted = true/false para silenciar sin cambiar el volume.", noShuffle:false },
  { concept_id:"dwec_u9_q20", unit:9, question:"¿Qué es la Screen Orientation API?", options:["Una API para capturar screenshots","Una API para bloquear u obtener la orientación de la pantalla del dispositivo (landscape/portrait)","Una API para ajustar el brillo de la pantalla","Una API para detectar monitores múltiples"], correct:1, explanation:"screen.orientation.type → 'landscape-primary', 'portrait-primary', etc. screen.orientation.lock('landscape') bloquea la orientación (solo en apps instaladas).", noShuffle:false },
  { concept_id:"dwec_u9_q21", unit:9, question:"¿Qué tipos de error puede devolver el callback de error de getCurrentPosition()?", options:["TIMEOUT, NO_GPS, DENIED","PERMISSION_DENIED, POSITION_UNAVAILABLE, TIMEOUT","GPS_OFF, NO_SIGNAL, USER_DENIED","NOT_FOUND, TIMEOUT, PERMISSION_ERROR"], correct:1, explanation:"GeolocationPositionError: code 1=PERMISSION_DENIED (usuario rechazó), 2=POSITION_UNAVAILABLE (fallo de hardware/red), 3=TIMEOUT (tiempo agotado).", noShuffle:false },
  { concept_id:"dwec_u9_q22", unit:9, question:"¿Cómo se captura una imagen de un vídeo en un elemento <canvas>?", options:["video.screenshot()","ctx.drawImage(videoElement, 0, 0) en un CanvasRenderingContext2D","canvas.capture(videoElement)","HTMLVideoElement.toImage()"], correct:1, explanation:"const ctx = canvas.getContext('2d'); ctx.drawImage(video, 0, 0, canvas.width, canvas.height); canvas.toDataURL('image/png') para obtener el dataURL.", noShuffle:false },
  { concept_id:"dwec_u9_q23", unit:9, question:"¿Qué hace la Picture-in-Picture API en JavaScript?", options:["Insertar una imagen dentro de otra","Mostrar un vídeo en una ventana flotante superpuesta que persiste aunque el usuario cambie de pestaña","Redimensionar vídeos para que quepan en el viewport","Crear collages de imágenes"], correct:1, explanation:"video.requestPictureInPicture() → mini reproductor flotante. document.exitPictureInPicture(). Soportado en Chrome, Edge y Firefox.", noShuffle:false },
  { concept_id:"dwec_u9_q24", unit:9, question:"¿Qué es el Media Session API?", options:["Una API para gestionar sesiones de usuario con vídeo","Una API que permite controlar metadatos del reproductor multimedia (título, artista, carátula) y los controles del sistema operativo","Una API para guardar el progreso de reproducción","Una API para gestionar múltiples reproductores en una página"], correct:1, explanation:"navigator.mediaSession.metadata = new MediaMetadata({title, artist, album, artwork}). Permite que los controles del SO (bloqueo de pantalla, auriculares) controlen el reproductor.", noShuffle:false },
  { concept_id:"dwec_u9_q25", unit:9, question:"¿Cómo se calcula la distancia entre dos puntos geográficos en JavaScript?", options:["Con la fórmula de la distancia euclidiana directamente","Con la fórmula de Haversine (que considera la curvatura de la Tierra) o con librerías como Turf.js","Con Math.distance(lat1,lng1,lat2,lng2)","Con navigator.geolocation.distance()"], correct:1, explanation:"Haversine: considera la curvatura terrestre. Para distancias cortas, la aproximación euclidiana puede ser válida. Librerías: Turf.js, geolib, Google Maps API.", noShuffle:false },
  { concept_id:"dwec_u9_q26", unit:9, question:"¿Qué es el Media Queries API de JavaScript (matchMedia)?", options:["Un procesador de consultas SQL para datos de media","Permite ejecutar lógica JS en respuesta a media queries CSS: window.matchMedia('(max-width:768px)').matches","Un inspector de archivos multimedia","Un servicio de metadatos de vídeos en línea"], correct:1, explanation:"matchMedia() devuelve un MediaQueryList con matches (boolean) y addListener para detectar cambios de viewport en JS.", noShuffle:false },
  { concept_id:"dwec_u9_q27", unit:9, question:"¿Qué información proporciona coords.heading en la Geolocation API?", options:["La altitud del dispositivo","La dirección de desplazamiento en grados desde el norte (0°=norte, 90°=este) o null si no está en movimiento","La velocidad horizontal en km/h","La distancia al siguiente checkpoint"], correct:1, explanation:"heading: grados [0,360) donde 0=norte, 90=este. Es null si el dispositivo está quieto o no tiene sensor de dirección.", noShuffle:false },
  { concept_id:"dwec_u9_q28", unit:9, question:"¿Qué es la Device Orientation API?", options:["Una API para rotar elementos del DOM","Una API que proporciona datos del giroscopio y acelerómetro del dispositivo: alpha, beta, gamma","Una API para detectar si el dispositivo es móvil o desktop","Una API para ajustar el volumen según la orientación"], correct:1, explanation:"DeviceOrientationEvent: alpha (rotación Z, brújula), beta (inclinación frontal/trasera), gamma (inclinación lateral). Requiere permiso en iOS 13+.", noShuffle:false },
  { concept_id:"dwec_u9_q29", unit:9, question:"¿Qué hace video.playbackRate = 2?", options:["Hace el vídeo 2 veces más pequeño","Reproduce el vídeo al doble de velocidad","Reproduce el vídeo en bucle 2 veces","Retrocede el vídeo 2 segundos"], correct:1, explanation:"playbackRate = 1 (normal), 2 (doble velocidad), 0.5 (mitad de velocidad), -1 (hacia atrás, no siempre soportado).", noShuffle:false },
  { concept_id:"dwec_u9_q30", unit:9, question:"¿Cómo se puede mostrar subtítulos (captions) en un vídeo HTML5?", options:["Con el elemento <subtitle> dentro de <video>","Con el elemento <track> dentro de <video> apuntando a un archivo VTT","Con un overlay de <p> posicionado sobre el vídeo","Con video.subtitles = 'archivo.srt'"], correct:1, explanation:"<track kind='subtitles' src='subs.vtt' srclang='es' label='Español'>. WebVTT es el formato estándar de subtítulos para HTML5.", noShuffle:false },
  { concept_id:"dwec_u9_q31", unit:9, question:"¿Qué API permite acceder a dispositivos de entrada multimedia (cámaras, micrófonos) del sistema?", options:["navigator.getUserMedia (deprecated)","navigator.mediaDevices.enumerateDevices() para listar y getUserMedia() para acceder","AudioInput API","DeviceAccess API"], correct:1, explanation:"enumerateDevices() lista las cámaras/micrófonos disponibles. getUserMedia() solicita acceso. Ambos en navigator.mediaDevices (interfaz MediaDevices).", noShuffle:false },
  { concept_id:"dwec_u9_q32", unit:9, question:"¿Qué es un plugin de vídeo y por qué han caído en desuso?", options:["Un efecto visual de vídeo","Software externo (Flash, Silverlight, QuickTime) necesario para reproducir multimedia; obsoleto porque HTML5 los reemplaza nativamente","Una extensión del formato MP4","Un tipo especial de códec"], correct:1, explanation:"Flash fue el más popular. HTML5 <audio>/<video> + codecs nativos + WebRTC eliminaron la necesidad de plugins externos, que además eran vectores de vulnerabilidades.", noShuffle:false },
  { concept_id:"dwec_u9_q33", unit:9, question:"¿Qué hace MediaRecorder API?", options:["Reproduce vídeos desde el servidor","Permite grabar audio/vídeo desde MediaStream (cámara, pantalla, etc.) directamente en el navegador","Transcribe audio a texto","Comprime vídeos para web"], correct:1, explanation:"MediaRecorder graba streams: new MediaRecorder(stream); recorder.start(); ... recorder.stop(); Datos en chunks via 'dataavailable'. Útil para grabar vídeos, notas de voz.", noShuffle:false },
  { concept_id:"dwec_u9_q34", unit:9, question:"¿Cómo se puede capturar el contenido de la pantalla del usuario en JavaScript?", options:["Con navigator.screen.capture()","Con navigator.mediaDevices.getDisplayMedia()","Con window.screenshot()","Con canvas.captureStream()"], correct:1, explanation:"getDisplayMedia() pide al usuario seleccionar qué compartir (pantalla, ventana o pestaña). Devuelve un MediaStream que se puede mostrar en <video> o grabar.", noShuffle:false },
  { concept_id:"dwec_u9_q35", unit:9, question:"¿Qué es la API de Notificaciones (Notifications API)?", options:["Las notificaciones de error en consola","Una API que permite a webs mostrar notificaciones del sistema operativo fuera del navegador, con permiso del usuario","Un sistema de mensajes dentro de la propia web","Las notificaciones de las DevTools"], correct:1, explanation:"Notification.requestPermission() → granted/denied. new Notification('Título', {body, icon, badge}). Las PWA las usan con Service Workers para enviarlas aunque la app esté cerrada.", noShuffle:false },
  { concept_id:"dwec_u9_q36", unit:9, question:"¿Para qué sirve la API de Vibración (Vibration API)?", options:["Para detectar si el dispositivo vibra","Para hacer vibrar el dispositivo del usuario mediante JavaScript","Para controlar el sonido del altavoz","Para indicar errores de formulario con vibración"], correct:1, explanation:"navigator.vibrate(200) → vibra 200ms. navigator.vibrate([200,100,200]) → patrón vibra-pausa-vibra. navigator.vibrate(0) → para la vibración.", noShuffle:false },
  { concept_id:"dwec_u9_q37", unit:9, question:"¿Qué es la Battery Status API?", options:["Una API para optimizar el rendimiento en batería baja","Una API para obtener el nivel de batería del dispositivo y si está cargando (desaconsejada por privacidad)","Una API para controlar el consumo de energía del SW","Una API exclusiva de dispositivos móviles"], correct:1, explanation:"navigator.getBattery() → {level:0-1, charging:bool, chargingTime, dischargingTime}. Limitada por privacidad (fingerprinting). Algunos navegadores la han eliminado.", noShuffle:false },
  { concept_id:"dwec_u9_q38", unit:9, question:"¿Qué propiedad CSS se usa junto con la API de Geolocalización para mostrar mapas interactivos?", options:["No hay relación entre CSS y la Geolocation API","La Geolocation API se usa con librerías como Leaflet.js o Google Maps API para renderizar mapas en elementos <div>","Solo SVG puede mostrar mapas","El elemento <map> de HTML5"], correct:1, explanation:"La Geolocation API da coordenadas. Leaflet, Mapbox, Google Maps o OpenLayers renderizan el mapa en un <div>. El mapa puede centrarse y marcar la posición del usuario.", noShuffle:false },
  { concept_id:"dwec_u9_q39", unit:9, question:"¿Cómo se reproduce un audio en JavaScript?", options:["Audio.play('archivo.mp3')","new Audio('archivo.mp3').play() o controlando un elemento <audio> del DOM","document.playAudio('archivo.mp3')","window.sound.play('archivo.mp3')"], correct:1, explanation:"const audio = new Audio('song.mp3'); audio.play(); — O: const el=document.querySelector('audio'); el.src='song.mp3'; el.play();", noShuffle:false },
  { concept_id:"dwec_u9_q40", unit:9, question:"¿Qué es el codec H.264 en el contexto de vídeo web?", options:["Un protocolo de streaming de vídeo","Un estándar de compresión de vídeo ampliamente compatible con navegadores y dispositivos; usado en archivos MP4","Un formato de archivo de vídeo","Un software de edición de vídeo"], correct:1, explanation:"H.264/AVC: el codec de vídeo más compatible. H.265 (HEVC) es más eficiente. VP9 y AV1 son alternativas libres de regalías populares en WebM.", noShuffle:false },
  { concept_id:"dwec_u9_q41", unit:9, question:"¿Qué evento de la Geolocation API indica que el usuario ha denegado el permiso de ubicación?", options:["geolocation.denied","El callback de error con code === GeolocationPositionError.PERMISSION_DENIED (1)","navigator.permissions.denied","window.onGeolocationError"], correct:1, explanation:"getCurrentPosition(success, error) — en error: if(err.code===1){} // PERMISSION_DENIED. Siempre implementar el callback de error para informar al usuario.", noShuffle:false },
  { concept_id:"dwec_u9_q42", unit:9, question:"¿Cómo se puede precargar recursos multimedia en HTML para mejorar la experiencia?", options:["Usando el atributo preload en <audio>/<video> o <link rel='preload'>","Con JavaScript manual usando fetch()","Los navegadores precargan automáticamente todo","Con el atributo src en el <head>"], correct:0, explanation:"<video preload='auto'> (carga todo), 'metadata' (solo info del vídeo) o 'none' (nada). <link rel='preload' as='video'> para priorizar la descarga del recurso.", noShuffle:false },
];
